// PLUTIOLABS LEAD SCRAPER v3 — CONFIG
// All client/run-specific values live here. Nothing hardcoded downstream.
try {
  // SUB-WORKFLOW MODE: when the parent invokes this workflow it passes its own
  // config in the payload. Returning it here means every downstream
  // $('⚙️ Config') reference keeps working unchanged, and the PARENT stays the
  // single source of truth - no config drift between parent and child.
  try {
    var incoming = $('🧩 Batch Input').first().json;
    if (incoming && incoming.config) { return [{ json: incoming.config }]; }
  } catch (subErr) { /* not running as a sub-workflow */ }

  return [{
    json: {
      // ---- API keys (fill before running enrichment stages) ----
      claudeApiKey:     'REPLACE_WITH_CLAUDE_API_KEY',
      apifyApiKey:      'REPLACE_WITH_APIFY_API_KEY',
      instantlyApiKey:  'REPLACE_WITH_INSTANTLY_API_KEY',
      zerobounceApiKey: 'REPLACE_WITH_ZEROBOUNCE_API_KEY',

      // ---- Storage ----
      sheetsId:          'YOUR_SCRAPER_SHEET_ID',
      sheetsTabName:     'Outreach CRM',
      sheetsSnapshotTab: 'MCS Snapshot',

      // ---- MCS source (Stage 1a) ----
      mcsIndexUrl:     'https://findcertifiedinstallers.co.uk/api/index.json',
      mcsInstallersUrl:'https://findcertifiedinstallers.co.uk/api/installers.json',

      // ---- Niche scope (Stage 1b) ----
      // MCS technologies that map to our solar + heat pump niche.
      mcsTechScope: ['solar_pv','ashp','battery','wshp','solar_thermal','eahp'],

      // PECR: only Ltd/LLP/plc are corporate subscribers (cold email allowed).
      emailOnlyLtd: true,

      // MEMORY CAP. The first full run (5,620 leads) crashed the n8n Cloud
      // instance at 47s with 0 nodes persisted - n8n retains every node's
      // input AND output, so a ~20-node chain holds ~20 copies of the dataset.
      // Keep this capped until the sub-workflow batching is built. 0 = unlimited.
      maxLeads: 500,
      // Offset into the filtered MCS list, for running sequential slices.
      // NOTE: slicing shrinks the competitor pool (F-R2) - a sliced run
      // produces WORSE competitor matching than one full-pool run. Only use
      // offsets once the parent/child batching shares one global index.
      leadOffset: 0,
      // Targeted repair: process ONLY these MCS certification numbers.
      // Empty array = normal full/capped run.
      onlyCerts: [],

      // ---- Google Maps discovery (Stage 1c — same niche, catches
      //      umbrella-scheme / lapsed / commercial installers MCS cannot see) ----
      apifyMaxResultsPerSearch: 40,
      // v2 polled 180 x 30s = 90 min inside a Code node and would hit the
      // n8n execution timeout, losing the entire scrape. Bounded here.
      apifyMaxPollMinutes: 20,
      // GATE 1 pilot cap: only look up this many MCS leads. Set to 0 for unlimited
      // once the match rate is proven >= 70%.
      apifyLookupLimit: 100,
      includeReviews: true,
      maxReviews: 20,
      ukCities: ['London','Manchester','Birmingham','Leeds'],
      ukKeywords: [
        'solar panel installer {city}',
        'solar PV installer {city}',
        'solar energy company {city}',
        'solar panel company {city}',
        'solar battery storage installer {city}',
        'solar installation {city}',
        'heat pump installer {city}',
        'air source heat pump installer {city}',
        'ground source heat pump installer {city}',
        'heat pump engineer {city}'
      ],

      // ---- Competitor match (Stage 3b) ----
      // Banded, NOT max: an unbanded pick returns median gap 224-554,
      // which names a national installer as a "local competitor".
      competitorRadiusMiles:   10,
      competitorRadiusFallback:15,
      competitorGapMin:        10,
      competitorGapMax:        150,

      // ---- ICP scoring (Stage 4) ----
      minReviewsForP1: 8,

      // ---- Review analysis (Stage 5/6) ----
      // Pass the LOWEST-rated reviews to Claude. Complaints live in 1-3 star
      // reviews; "most relevant" skews 5-star and topComplaint comes back empty.
      // Send BOTH ends of the rating distribution to Claude in one call:
      // lowest-rated carry the complaint (Template A/B), highest-rated carry
      // the quote (Template A-v2). Sending only lowest would kill A-v2.
      reviewsLowCount: 5,
      reviewsHighCount: 3,
      // GATE 2 pilot cap on Claude calls. Set to 0 for unlimited after measuring.
      maxClaudeCalls: 100,
      // Instantly is now only called where it adds something (see Enrich node).
      maxInstantlyCalls: 0,
      // GATE 3 pilot cap. ZeroBounce free tier is 100/month - check your plan
      // before raising this for a 5,000-lead run.
      maxVerifyCalls: 200
    }
  }];
} catch (e) {
  return [{ json: { _error: 'Config failed: ' + e.message } }];
}

// Stage 1a — split the MCS installers array into one item per lead.
try {
  var payload = $input.first().json;
  var rows = (payload && payload.installers) ? payload.installers : [];

  var idx = {};
  try { idx = $('📡 Fetch MCS Index').first().json || {}; } catch (e) { idx = {}; }
  var generatedAt = idx.generated_at || '';

  if (!rows.length) {
    return [{ json: { _error: 'MCS fetch returned no installers', _count: 0 } }];
  }

  var out = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    r.source = 'mcs';
    r.mcsGeneratedAt = generatedAt;
    out.push({ json: r });
  }
  return out;
} catch (e) {
  return [{ json: { _error: 'Split MCS failed: ' + e.message } }];
}

// Stage 1b — scope filter + the 5 mandatory fixes from the 2026-08-15 data audit.
try {
  var cfg = $('⚙️ Config').first().json;
  var scope = cfg.mcsTechScope || [];
  var ltdOnly = cfg.emailOnlyLtd !== false;
  var maxLeads = cfg.maxLeads || 0;
  var onlyCerts = cfg.onlyCerts || [];
  var leadOffset = cfg.leadOffset || 0;
  var matchedIdx = 0;
  var items = $input.all();

  var FREE = ['gmail.com','hotmail.com','hotmail.co.uk','yahoo.com','yahoo.co.uk',
              'outlook.com','icloud.com','btinternet.com','live.co.uk','aol.com',
              'sky.com','msn.com','me.com'];

  // Scotland / Wales / NI postcode areas. `region` is England-only — never filter on it.
  var SCOT = ['AB','DD','DG','EH','FK','G','HS','IV','KA','KW','KY','ML','PA','PH','TD','ZE'];
  var WALES = ['CF','LD','LL','NP','SA'];

  function pcArea(pc) {
    var m = String(pc || '').toUpperCase().match(/^[A-Z]{1,2}/);
    return m ? m[0] : '';
  }
  function country(pc) {
    var a = pcArea(pc);
    if (a === 'BT') return 'Northern Ireland';
    if (SCOT.indexOf(a) !== -1) return 'Scotland';
    if (WALES.indexOf(a) !== -1) return 'Wales';
    return 'England';
  }
  function isLtd(name) {
    var n = String(name || '').toLowerCase().replace(/\.+$/, '').trim();
    return /\b(ltd|limited|llp|plc)$/.test(n);
  }
  function fixSite(w) {
    var s = String(w || '').trim();
    if (!s) return '';
    if (/\s/.test(s)) return '';                 // embedded space = malformed
    if (!/\.[a-z]{2,}/i.test(s)) return '';       // no TLD = malformed
    if (!/^https?:\/\//i.test(s)) s = 'https://' + s;  // FIX: 83.2% lack a scheme
    return s.replace(/\/+$/, '');
  }
  function normPhone(p) {
    var d = String(p || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) d = d.substring(2);
    if (d.indexOf('0') === 0) d = d.substring(1);
    // F-R7 FIX: preserve non-standard lengths. Returning '' for anything that
    // wasn't exactly 10 digits destroyed 23 working phone numbers AND created
    // blank match keys, which let appendOrUpdate overwrite one business's row
    // with another's (F-R6 - lost 'C Keightley Ltd t/a BoilerCert').
    return d.length >= 7 ? d : '';
  }
  // v2's normalizer emits +44 format. Must match or the merge dedupe silently fails.
  function e164(k) { return k ? '+44' + k : ''; }

  var out = [];
  var stats = { seen: 0, outOfScope: 0, notLtd: 0, badGeo: 0, kept: 0,
                pecrRisk: 0, badSite: 0, badPhone: 0, skippedByOffset: 0 };

  for (var i = 0; i < items.length; i++) {
    if (maxLeads > 0 && out.length >= maxLeads) { stats.capped = true; break; }
    var r = items[i].json;
    if (!r || r._error) { continue; }
    stats.seen++;

    // Targeted repair mode: process only these certification numbers.
    if (onlyCerts.length && onlyCerts.indexOf(r.certification_number) === -1) { continue; }

    var techs = r.technologies || [];
    var inScope = false;
    for (var t = 0; t < techs.length; t++) {
      if (scope.indexOf(techs[t]) !== -1) { inScope = true; break; }
    }
    if (!inScope) { stats.outOfScope++; continue; }

    // FIX: drop rows outside the UK bounding box (2 known junk rows)
    var lat = Number(r.latitude), lon = Number(r.longitude);
    if (!(lat >= 49.8 && lat <= 60.9 && lon >= -8.7 && lon <= 1.9)) {
      stats.badGeo++; continue;
    }

    // Offset slicing: skip the first N in-scope leads.
    matchedIdx++;
    if (leadOffset > 0 && matchedIdx <= leadOffset) { stats.skippedByOffset++; continue; }

    var ltd = isLtd(r.name);
    if (ltdOnly && !ltd) { stats.notLtd++; }

    var site = fixSite(r.website);
    if (r.website && !site) { stats.badSite++; }

    var phone = normPhone(r.telephone);
    if (r.telephone && !phone) { stats.badPhone++; }

    var email = String(r.email || '').trim().toLowerCase();
    var emailDomain = email.indexOf('@') > -1 ? email.split('@')[1] : '';
    var freeMailbox = FREE.indexOf(emailDomain) !== -1;
    var emailValid = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email);

    // PECR: sole-trader signal = free mailbox AND no Ltd suffix -> phone only
    var pecrRisk = (!ltd && freeMailbox);
    if (pecrRisk) { stats.pecrRisk++; }

    var emailable = emailValid && !pecrRisk && (!ltdOnly || ltd);

    stats.kept++;
    out.push({ json: {
      source: 'mcs',
      mcsGeneratedAt: r.mcsGeneratedAt || '',
      companyName: r.name,
      certNumber: r.certification_number,
      certBody: r.certification_body,
      technologies: techs.join(', '),
      busRegistered: !!r.bus_registered,
      address: r.address,
      postcode: r.postcode,
      town: r.town,
      county: r.county,
      country: country(r.postcode),
      latitude: lat,
      longitude: lon,
      phone: e164(phone),
      phoneKey: phone,
      phoneRaw: r.telephone || '',
      email: email,
      emailValid: emailValid,
      emailFreeMailbox: freeMailbox,
      website: site,
      googleRating: (r.google_rating === null || r.google_rating === undefined) ? null : Number(r.google_rating),
      reviewCount: (r.google_review_count === null || r.google_review_count === undefined) ? null : Number(r.google_review_count),
      googleMatched: (r.google_review_count !== null && r.google_review_count !== undefined),
      entityType: ltd ? 'ltd' : 'unknown',
      pecrRisk: pecrRisk,
      emailable: emailable,
      mcsPageUrl: r.page_url || ''
    }});
  }

  if (!out.length) {
    return [{ json: { _error: 'MCS filter produced 0 leads', _stats: stats } }];
  }
  out[0].json._stats = stats;
  return out;
} catch (e) {
  return [{ json: { _error: 'MCS filter failed: ' + e.message } }];
}

// Diagnostic — prints the real funnel so we can see what we actually have
// before spending a penny on Apify / Claude / Instantly.
try {
  var items = $input.all();
  var s = { total: 0, emailable: 0, ltd: 0, pecrRisk: 0, withWebsite: 0,
            withGoogleData: 0, p1Ready: 0, busRegistered: 0 };
  var byCountry = {}, byCertBody = {}, byTech = {};
  var minRev = ($('⚙️ Config').first().json.minReviewsForP1) || 8;
  var filterStats = null;

  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    if (r._stats) { filterStats = r._stats; }
    s.total++;
    if (r.emailable) { s.emailable++; }
    if (r.entityType === 'ltd') { s.ltd++; }
    if (r.pecrRisk) { s.pecrRisk++; }
    if (r.website) { s.withWebsite++; }
    if (r.googleMatched) { s.withGoogleData++; }
    if (r.busRegistered) { s.busRegistered++; }
    if (r.website && r.reviewCount !== null && r.reviewCount >= minRev) { s.p1Ready++; }

    byCountry[r.country] = (byCountry[r.country] || 0) + 1;
    byCertBody[r.certBody] = (byCertBody[r.certBody] || 0) + 1;
    var techs = String(r.technologies || '').split(', ');
    for (var t = 0; t < techs.length; t++) {
      if (techs[t]) { byTech[techs[t]] = (byTech[techs[t]] || 0) + 1; }
    }
  }

  return [{ json: {
    _summary: 'MCS Stage 1a/1b complete',
    mcsGeneratedAt: items.length ? (items[0].json.mcsGeneratedAt || 'unknown') : 'unknown',
    counts: s,
    filterStats: filterStats,
    byCountry: byCountry,
    byCertBody: byCertBody,
    byTechnology: byTech,
    note: 'p1Ready counts only leads whose review data MCS already carries (~47%). Apify Tier-1 lookup fills the rest.'
  }}];
} catch (e) {
  return [{ json: { _error: 'Summary failed: ' + e.message } }];
}

// Stage 1c — Google Maps keyword discovery (ported from v2 + 4 fixes).
// Purpose: catch umbrella-scheme / lapsed / commercial installers MCS cannot see.
var config = $('⚙️ Config').first().json;
var apifyKey = config.apifyApiKey || '';
var cities = config.ukCities || [];
var keywords = config.ukKeywords || [];
var maxResults = config.apifyMaxResultsPerSearch || 40;
var inclReviews = config.includeReviews !== false;
var maxRev = config.maxReviews || 20;
var maxPolls = (config.apifyMaxPollMinutes || 20) * 2;  // FIX: 30s per poll, bounded
var ukLeads = [];

// FIX: graceful skip so the MCS branch still runs before the Apify key exists.
if (!apifyKey || apifyKey.indexOf('REPLACE_WITH') === 0) {
  return [{ json: { _skipped: true, source: 'maps', _note: 'Apify key not set - Maps discovery skipped, MCS branch continues' } }];
}

var searchStrings = [];
for (var ci = 0; ci < cities.length; ci++) {
  for (var ki = 0; ki < keywords.length; ki++) {
    searchStrings.push(keywords[ki].replace('{city}', cities[ci]));
  }
}

try {
  var startRes = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/compass~crawler-google-places/runs?waitForFinish=0',
    headers: { 'Authorization': 'Bearer ' + apifyKey, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: maxResults,
      language: 'en',
      includeWebResults: false,
      includeReviews: inclReviews,
      maxReviews: maxRev,
      reviewsSort: 'newest'
    })
  });

  var runId = startRes.data.id;
  var datasetId = startRes.data.defaultDatasetId;

  var runStatus = 'RUNNING';
  var pollCount = 0;
  while (runStatus !== 'SUCCEEDED' && runStatus !== 'FAILED' && runStatus !== 'ABORTED' && pollCount < maxPolls) {
    await new Promise(function(done) { setTimeout(done, 30000); });
    var statusRes = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/actor-runs/' + runId,
      headers: { 'Authorization': 'Bearer ' + apifyKey }
    });
    runStatus = statusRes.data.status;
    pollCount++;
  }

  if (runStatus !== 'SUCCEEDED') {
    throw new Error('Apify run ' + runStatus + ' after ' + (pollCount * 30) + 's (ceiling ' + maxPolls + ' polls)');
  }

  var allPlaces = [];
  var offset = 0;
  var fetchDone = false;
  while (!fetchDone) {
    var batch = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items?format=json&limit=500&offset=' + offset,
      headers: { 'Authorization': 'Bearer ' + apifyKey }
    });
    if (!batch || batch.length === 0) {
      fetchDone = true;
    } else {
      for (var bi = 0; bi < batch.length; bi++) { allPlaces.push(batch[bi]); }
      fetchDone = batch.length < 500;
      offset += 500;
    }
  }

  for (var k = 0; k < allPlaces.length; k++) {
    var p = allPlaces[k];
    if (p.permanentlyClosed || p.temporarilyClosed) { continue; }
    if (!p.phone && !p.website) { continue; }

    var social = p.socialMediaLinks || {};
    var socialArr = [];
    if (Array.isArray(social)) {
      for (var mi = 0; mi < social.length; mi++) {
        var sm = social[mi];
        if (typeof sm === 'string') { socialArr.push(sm); }
        else if (sm && sm.url) { socialArr.push(sm.url); }
      }
    } else {
      var sKeys = Object.keys(social);
      for (var mj = 0; mj < sKeys.length; mj++) {
        if (social[sKeys[mj]]) { socialArr.push(social[sKeys[mj]]); }
      }
    }

    // NEW: capture published WhatsApp click-to-chat links (public, on their own listing)
    var waLink = '';
    for (var wi = 0; wi < socialArr.length; wi++) {
      var sl = String(socialArr[wi]).toLowerCase();
      if (sl.indexOf('wa.me') !== -1 || sl.indexOf('api.whatsapp.com') !== -1) {
        waLink = socialArr[wi];
        break;
      }
    }

    var hours = '';
    if (p.openingHours && p.openingHours.length) {
      var hParts = [];
      for (var hi = 0; hi < p.openingHours.length; hi++) {
        var oh = p.openingHours[hi];
        if (!oh) { continue; }
        if (oh.day && oh.hours) { hParts.push(oh.day + ': ' + oh.hours); }
        else if (typeof oh === 'string') { hParts.push(oh); }
      }
      hours = hParts.join(' | ');
    }

    var cats = p.categories ? p.categories.join(', ') : (p.categoryName || '');

    var attrs = [];
    if (p.additionalInfo) {
      var aiSections = Object.keys(p.additionalInfo);
      for (var ai = 0; ai < aiSections.length; ai++) {
        var sec = p.additionalInfo[aiSections[ai]];
        if (!sec || typeof sec !== 'object') { continue; }
        var secKeys = Object.keys(sec);
        for (var si = 0; si < secKeys.length; si++) {
          if (sec[secKeys[si]] === true) { attrs.push(secKeys[si]); }
        }
      }
    }

    var city = p.city || '';
    if (!city && p.searchString) {
      var sLower = p.searchString.toLowerCase();
      for (var cfi = 0; cfi < cities.length; cfi++) {
        if (sLower.indexOf(cities[cfi].toLowerCase()) !== -1) { city = cities[cfi]; break; }
      }
    }

    // NEW: capture coordinates — required by the geospatial competitor match.
    // v2 discarded these, which would have left every Maps lead unmatchable.
    var lat = null, lon = null;
    if (p.location) {
      lat = (p.location.lat !== undefined) ? p.location.lat : null;
      lon = (p.location.lng !== undefined) ? p.location.lng : null;
    }

    ukLeads.push({ json: {
      companyName:        p.title || '',
      city:               city,
      postcode:           p.postalCode || '',
      address:            p.address || '',
      phone:              p.phone || '',
      website:            p.website || '',
      email:              '',
      source:             'maps',
      googleRating:       p.totalScore || 0,
      reviewCount:        p.reviewsCount || 0,
      googleMapsUrl:      p.url || '',
      categories:         cats,
      openingHours:       hours,
      businessAttributes: attrs.join(', '),
      socialLinks:        socialArr.join(', '),
      waLink:             waLink,
      latitude:           lat,
      longitude:          lon,
      reviews:            p.reviews || []
    }});
  }
} catch (e) {
  return [{ json: { _skipped: true, source: 'maps', _error: 'Google Maps: ' + e.message } }];
}

return ukLeads;

// Stage 1d — reconcile MCS + Maps into ONE canonical record shape, then dedupe.
// Subsumes v2's '🔧 Normalize & Deduplicate' (same dedupe keys, single pass).
try {
  var items = $input.all();

  // FIX F-A1: MCS rows have no `categories`. Synthesise one from `technologies`
  // so v2's getTradeLabel / getTradeScene / getTradeGroup work UNCHANGED.
  var TECH_LABEL = {
    solar_pv: 'Solar panel installer', solar_thermal: 'Solar thermal installer',
    battery: 'Solar battery storage', ashp: 'Heat pump installer',
    wshp: 'Heat pump installer', eahp: 'Heat pump installer',
    gshp: 'Heat pump installer', sahp: 'Heat pump installer',
    gahp: 'Heat pump installer', biomass: 'Biomass installer',
    wind_turbine: 'Wind turbine installer', micro_chp: 'Micro CHP installer'
  };
  var TECH_ORDER = ['solar_pv','solar_thermal','battery','ashp','wshp','eahp',
                    'gshp','sahp','gahp','biomass','wind_turbine','micro_chp'];

  function techToCategories(techStr) {
    var raw = String(techStr || '').split(',');
    var have = {};
    for (var i = 0; i < raw.length; i++) {
      var t = raw[i].replace(/\s/g, '');
      if (t) { have[t] = true; }
    }
    var out = [];
    for (var o = 0; o < TECH_ORDER.length; o++) {
      var key = TECH_ORDER[o];
      if (have[key]) {
        var lab = TECH_LABEL[key];
        if (lab && out.indexOf(lab) === -1) { out.push(lab); }
      }
    }
    return out.join(', ');
  }

  function normPhone(phone) {
    var raw = String(phone || '');
    var p = '';
    for (var ci = 0; ci < raw.length; ci++) {
      var ch = raw.charAt(ci);
      if (ch >= '0' && ch <= '9') { p += ch; }
      else if (ch === '+' && p.length === 0) { p += ch; }
    }
    if (p.length < 5) { return ''; }
    if (p.charAt(0) === '+') { return p; }
    if (p.charAt(0) === '0') { return '+44' + p.substring(1); }
    if (p.length > 10 && p.substring(0, 2) === '44') { return '+' + p; }
    return p;
  }
  function phoneKeyOf(e164) {
    var d = String(e164 || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) { d = d.substring(2); }
    if (d.indexOf('0') === 0) { d = d.substring(1); }
    return d.length >= 7 ? d : '';   // F-R7: preserve non-standard lengths
  }
  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function isMob(e164) { return String(e164 || '').indexOf('+447') === 0; }

  function canonMcs(r) {
    var ph = r.phone || '';
    return {
      companyName: r.companyName || '', city: r.town || '', country: 'UK',
      ukCountry: r.country || '', postcode: r.postcode || '', county: r.county || '',
      address: r.address || '',
      phone: ph, phoneKey: r.phoneKey || phoneKeyOf(ph),
      website: r.website || '', email: r.email || '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'mcs',
      googleRating: r.googleRating || 0,
      reviewCount: (r.reviewCount === null || r.reviewCount === undefined) ? 0 : r.reviewCount,
      googleMatched: !!r.googleMatched,
      googleMapsUrl: '', categories: techToCategories(r.technologies),
      openingHours: '', hoursKnown: false,
      businessAttributes: '', socialLinks: '', reviews: [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: r.certNumber || '', certBody: r.certBody || '',
      technologies: r.technologies || '', busRegistered: !!r.busRegistered,
      entityType: r.entityType || 'unknown', pecrRisk: !!r.pecrRisk,
      emailable: !!r.emailable, emailSource: r.email ? 'mcs' : '',
      mcsGeneratedAt: r.mcsGeneratedAt || '', mcsPageUrl: r.mcsPageUrl || '',
      isMobile: isMob(ph), waLink: ''
    };
  }

  function canonMaps(r) {
    var ph = normPhone(r.phone);
    return {
      companyName: r.companyName || '', city: r.city || '', country: 'UK',
      ukCountry: '', postcode: r.postcode || '', county: '', address: r.address || '',
      phone: ph, phoneKey: phoneKeyOf(ph),
      website: r.website || '', email: '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'maps',
      googleRating: r.googleRating || 0, reviewCount: r.reviewCount || 0,
      googleMatched: true,
      googleMapsUrl: r.googleMapsUrl || '', categories: r.categories || '',
      openingHours: r.openingHours || '', hoursKnown: !!r.openingHours,
      businessAttributes: r.businessAttributes || '', socialLinks: r.socialLinks || '',
      reviews: r.reviews || [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: '', certBody: '', technologies: '', busRegistered: false,
      entityType: 'unknown', pecrRisk: false, emailable: false, emailSource: '',
      mcsGeneratedAt: '', mcsPageUrl: '',
      isMobile: isMob(ph), waLink: r.waLink || ''
    };
  }

  var byPhone = {}, byDomain = {};
  var out = [];
  var stats = { mcsIn: 0, mapsIn: 0, mapsSkipped: 0, merged: 0, mapsNetNew: 0, dropped: 0 };

  // Pass 1 — MCS is the base list.
  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error || r._skipped) {
      if (r && r._skipped) { stats.mapsSkipped++; }
      continue;
    }
    if (r.source !== 'mcs') { continue; }
    stats.mcsIn++;
    var c = canonMcs(r);
    if (!c.companyName) { stats.dropped++; continue; }
    out.push(c);
    if (c.phoneKey) { byPhone[c.phoneKey] = c; }
    var d = domainOf(c.website);
    if (d) { byDomain[d] = c; }
  }

  // Pass 2 — Maps rows either enrich an existing MCS row or become net-new leads.
  for (var j = 0; j < items.length; j++) {
    var m = items[j].json;
    if (!m || m._error || m._skipped) { continue; }
    if (m.source !== 'maps') { continue; }
    stats.mapsIn++;

    var cm = canonMaps(m);
    if (!cm.companyName) { stats.dropped++; continue; }

    var dm = domainOf(cm.website);
    var hit = null;
    if (cm.phoneKey && byPhone[cm.phoneKey]) { hit = byPhone[cm.phoneKey]; }
    else if (dm && byDomain[dm]) { hit = byDomain[dm]; }

    if (hit) {
      // Precedence: MCS wins identity/contact, Maps wins Google intelligence.
      hit.source = 'both';
      hit.googleRating = cm.googleRating || hit.googleRating;
      hit.reviewCount = cm.reviewCount || hit.reviewCount;
      hit.googleMatched = true;
      hit.googleMapsUrl = cm.googleMapsUrl || hit.googleMapsUrl;
      hit.openingHours = cm.openingHours || hit.openingHours;
      hit.hoursKnown = hit.hoursKnown || cm.hoursKnown;
      hit.businessAttributes = cm.businessAttributes || hit.businessAttributes;
      hit.socialLinks = cm.socialLinks || hit.socialLinks;
      hit.reviews = (cm.reviews && cm.reviews.length) ? cm.reviews : hit.reviews;
      hit.waLink = hit.waLink || cm.waLink;
      if (!hit.categories) { hit.categories = cm.categories; }
      if (!hit.website) { hit.website = cm.website; }
      if (hit.latitude === null || hit.latitude === undefined) { hit.latitude = cm.latitude; }
      if (hit.longitude === null || hit.longitude === undefined) { hit.longitude = cm.longitude; }
      stats.merged++;
    } else {
      out.push(cm);
      if (cm.phoneKey) { byPhone[cm.phoneKey] = cm; }
      if (dm) { byDomain[dm] = cm; }
      stats.mapsNetNew++;
    }
  }

  // WhatsApp signal (step 15). Public sources only — never a registration check.
  for (var k = 0; k < out.length; k++) {
    var o = out[k];
    if (o.waLink) { o.waSignal = 'wa-link'; o.waNumber = o.phone; }
    else if (o.isMobile) { o.waSignal = 'mobile'; o.waNumber = o.phone; }
    else { o.waSignal = 'none'; o.waNumber = ''; }
  }

  // 'both' first — richest records lead the export.
  out.sort(function(a, b) {
    var rank = { both: 0, mcs: 1, maps: 2 };
    return (rank[a.source] || 3) - (rank[b.source] || 3);
  });

  if (!out.length) {
    return [{ json: { _error: 'Reconcile produced 0 leads', _stats: stats } }];
  }

  var results = [];
  for (var z = 0; z < out.length; z++) { results.push({ json: out[z] }); }
  results[0].json._reconcileStats = stats;
  return results;
} catch (e) {
  return [{ json: { _error: 'Reconcile failed: ' + e.message } }];
}

// Stage 3b — REWRITTEN. Geospatial join over the merged list.
// v2 grouped by lowercased city STRING and took the max-review peer. That breaks
// on merged data (MCS towns like 'Tonbridge and Malling' never match 'London')
// and an unbanded max names a national installer as a 'local competitor'
// (measured median gap 224-554, not credible to a tradesman).
try {
  var cfg = $('⚙️ Config').first().json;
  var R1 = cfg.competitorRadiusMiles || 10;
  var R2 = cfg.competitorRadiusFallback || 15;
  var GMIN = cfg.competitorGapMin || 10;
  var GMAX = cfg.competitorGapMax || 150;

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Competitor Match got 0 leads' } }]; }

  function tradeGroup(categories) {
    if (!categories) { return 'general'; }
    var c = String(categories).toLowerCase();
    if (c.indexOf('solar') !== -1 || c.indexOf('panel') !== -1) { return 'solar'; }
    if (c.indexOf('heat pump') !== -1 || c.indexOf('heatpump') !== -1) { return 'heatpump'; }
    if (c.indexOf('boiler') !== -1 || c.indexOf('heating') !== -1 || c.indexOf('plumb') !== -1) { return 'heating'; }
    if (c.indexOf('insul') !== -1) { return 'insulation'; }
    if (c.indexOf('hvac') !== -1 || c.indexOf('air con') !== -1 || c.indexOf('cooling') !== -1) { return 'hvac'; }
    if (c.indexOf('electr') !== -1) { return 'electrical'; }
    if (c.indexOf('roofing') !== -1 || c.indexOf('roof') !== -1) { return 'roofing'; }
    if (c.indexOf('renovat') !== -1 || c.indexOf('builder') !== -1) { return 'renovation'; }
    if (c.indexOf('window') !== -1 || c.indexOf('glazing') !== -1) { return 'glazing'; }
    return 'general';
  }

  // Grid index (~0.25 deg cells) so this stays O(n) rather than O(n^2) at 5k leads.
  var CELL = 0.25;
  var grid = {};
  var pool = [];

  // F-R2 FIX: match against the parent's GLOBAL index when running as a
  // sub-workflow, so a 500-lead batch still sees the whole 5,600-lead pool.
  // Measured: full pool matches ~100% of eligible leads, a 500-lead slice 48.6%.
  // Falls back to the local batch when running standalone.
  var poolSrc = leads;
  var usingGlobalIndex = false;
  try {
    var bi = $('🧩 Batch Input').first().json;
    if (bi && bi.index && bi.index.length) { poolSrc = bi.index; usingGlobalIndex = true; }
  } catch (e) { /* standalone */ }

  // Identity key so a lead never matches itself in the global index
  // (object identity does not hold across the parent/child boundary).
  function idKey(x) {
    if (x.certNumber) { return 'MCS:' + x.certNumber; }
    if (x.key) { return x.key; }
    return 'NM:' + String(x.companyName || '').toLowerCase();
  }
  for (var q = 0; q < leads.length; q++) {
    leads[q]._tg = tradeGroup(leads[q].categories);
    leads[q]._key = idKey(leads[q]);
  }

  for (var p = 0; p < poolSrc.length; p++) {
    var L = poolSrc[p];
    L._tg = tradeGroup(L.categories);
    L._key = idKey(L);
    if (typeof L.latitude !== 'number' || typeof L.longitude !== 'number') { continue; }
    if (!L.reviewCount || L.reviewCount <= 0) { continue; }
    var gk = Math.round(L.latitude / CELL) + ':' + Math.round(L.longitude / CELL);
    if (!grid[gk]) { grid[gk] = []; }
    grid[gk].push(L);
    pool.push(L);
  }

  function milesBetween(a, b) {
    var dLat = (b.latitude - a.latitude) * 69;
    var dLon = (b.longitude - a.longitude) * 69 * Math.cos(a.latitude * Math.PI / 180);
    return Math.sqrt(dLat * dLat + dLon * dLon);
  }

  function candidates(L, miles) {
    var found = [];
    var cy = Math.round(L.latitude / CELL);
    var cx = Math.round(L.longitude / CELL);
    var span = Math.ceil(miles / 12) + 1;
    for (var dy = -span; dy <= span; dy++) {
      for (var dx = -span; dx <= span; dx++) {
        var cellList = grid[(cy + dy) + ':' + (cx + dx)];
        if (!cellList) { continue; }
        for (var z = 0; z < cellList.length; z++) {
          var o = cellList[z];
          if (o === L) { continue; }
          if (o._key && L._key && o._key === L._key) { continue; }
          if (milesBetween(L, o) <= miles) { found.push(o); }
        }
      }
    }
    return found;
  }

  function pick(L, miles, sameTrade) {
    var cands = candidates(L, miles);
    var best = null;
    for (var c = 0; c < cands.length; c++) {
      var o = cands[c];
      if (sameTrade && o._tg !== L._tg) { continue; }
      var gap = (o.reviewCount || 0) - (L.reviewCount || 0);
      if (gap < GMIN || gap > GMAX) { continue; }
      if (!best || o.reviewCount > best.reviewCount) { best = o; }
    }
    return best;
  }

  var stats = { poolSize: pool.length, usingGlobalIndex: usingGlobalIndex,
                matched: 0, tier1: 0, tier2: 0, tier3: 0, none: 0 };

  for (var j = 0; j < leads.length; j++) {
    var lead = leads[j];
    var comp = null;
    var tier = '';

    if (typeof lead.latitude === 'number' && typeof lead.longitude === 'number' && lead.reviewCount > 0) {
      comp = pick(lead, R1, true);
      if (comp) { tier = 'same-trade-' + R1 + 'mi'; stats.tier1++; }
      if (!comp) {
        comp = pick(lead, R2, true);
        if (comp) { tier = 'same-trade-' + R2 + 'mi'; stats.tier2++; }
      }
      if (!comp) {
        comp = pick(lead, R1, false);
        if (comp) { tier = 'any-trade-' + R1 + 'mi'; stats.tier3++; }
      }
    }

    if (comp) {
      lead.competitorName = comp.companyName || '';
      lead.competitorRating = comp.googleRating || 0;
      lead.competitorReviews = comp.reviewCount || 0;
      lead.competitorOpeningHours = comp.openingHours || '';
      lead.competitorDistanceMiles = Math.round(milesBetween(lead, comp) * 10) / 10;
      lead.competitorTier = tier;
      stats.matched++;
    } else {
      lead.competitorName = '';
      lead.competitorRating = 0;
      lead.competitorReviews = 0;
      lead.competitorOpeningHours = '';
      lead.competitorDistanceMiles = null;
      lead.competitorTier = 'none';
      stats.none++;
    }
    delete lead._tg;
  }

  var results = [];
  for (var r = 0; r < leads.length; r++) { results.push({ json: leads[r] }); }
  results[0].json._competitorStats = stats;
  return results;
} catch (e) {
  return [{ json: { _error: 'Competitor Match failed: ' + e.message } }];
}

// Stage 4 — ICP scoring.
// Two changes vs v2:
//  1. review threshold 10 -> configurable (8). Dataset p25 is 6, median 17;
//     10 was discarding a usable band.
//  2. 'has contact' now accepts an MCS email, not just a website. The website
//     requirement only ever existed because Instantly needs a domain.
try {
  var cfg = $('⚙️ Config').first().json;
  var minRev = cfg.minReviewsForP1 || 8;

  var items = $input.all();
  var results = [];
  var stats = { p1: 0, p2: 0, noContact: 0 };

  for (var i = 0; i < items.length; i++) {
    var lead = items[i].json;
    if (!lead || lead._error) { results.push({ json: lead }); continue; }

    var hasContact = !!(lead.website || lead.email);
    if (!hasContact) { stats.noContact++; }

    var priority = (hasContact && (lead.reviewCount || 0) >= minRev) ? '1' : '2';
    if (priority === '1') { stats.p1++; } else { stats.p2++; }

    lead.priority = priority;
    results.push({ json: lead });
  }

  results.sort(function(a, b) {
    var ap = (a.json && a.json.priority) ? a.json.priority : '9';
    var bp = (b.json && b.json.priority) ? b.json.priority : '9';
    return ap.localeCompare(bp);
  });

  if (results.length) { results[0].json._icpStats = stats; }
  return results;
} catch (e) {
  return [{ json: { _error: 'ICP Score failed: ' + e.message } }];
}

// Stage 10 — assemble the CRM row. Output keys ARE the Sheet column headers
// (the Sheets node uses autoMapInputData), so these strings must match exactly.
//
// Changes vs v2:
//  1. F-A3 fix: unknown opening hours no longer report 'Hours Gap = TRUE'.
//  2. LinkedIn message generation removed. It carried HARDCODED FABRICATED
//     client results (barJobs/barWeeks/barCity). The WhatsApp replacement makes
//     NO performance claims until a real case study exists.
//  3. New MCS + WhatsApp columns appended.
try {
  var items = $input.all();
  var today = new Date().toISOString().split('T')[0];
  // Read defensively - this node has never needed config before (LEVER 3).
  var cfgR = {};
  try { cfgR = $('⚙️ Config').first().json || {}; } catch (eCfg) { }
  var results = [];

  function getTradeScene(categories) {
    if (!categories) { return 'out on a job'; }
    var cat = String(categories).toLowerCase();
    if (cat.indexOf('solar') !== -1 || cat.indexOf('panel') !== -1) { return 'on a roof fitting panels'; }
    if (cat.indexOf('heat pump') !== -1 || cat.indexOf('heatpump') !== -1) { return 'commissioning a heat pump system'; }
    if (cat.indexOf('boiler') !== -1) { return 'in a plant room fitting a boiler'; }
    if (cat.indexOf('heating') !== -1 || cat.indexOf('plumb') !== -1) { return 'in a plant room fitting a boiler'; }
    if (cat.indexOf('insul') !== -1) { return 'installing insulation in a loft'; }
    if (cat.indexOf('electr') !== -1) { return 'on a job wiring a property'; }
    if (cat.indexOf('hvac') !== -1 || cat.indexOf('air con') !== -1 || cat.indexOf('cooling') !== -1) { return 'fitting an air conditioning unit'; }
    if (cat.indexOf('renovat') !== -1 || cat.indexOf('builder') !== -1) { return 'on site running a job'; }
    if (cat.indexOf('window') !== -1 || cat.indexOf('glazing') !== -1) { return 'on a job fitting windows'; }
    if (cat.indexOf('roofing') !== -1 || cat.indexOf('roof') !== -1) { return 'up on a roof'; }
    return 'out on a job';
  }

  function getTradeLabel(categories) {
    if (!categories) { return 'trade'; }
    var cat = String(categories).toLowerCase();
    if (cat.indexOf('solar') !== -1 || cat.indexOf('panel') !== -1) { return 'solar installer'; }
    if (cat.indexOf('heat pump') !== -1 || cat.indexOf('heatpump') !== -1) { return 'heat pump installer'; }
    if (cat.indexOf('boiler') !== -1) { return 'boiler engineer'; }
    if (cat.indexOf('heating') !== -1 || cat.indexOf('plumb') !== -1) { return 'heating engineer'; }
    if (cat.indexOf('insul') !== -1) { return 'insulation installer'; }
    if (cat.indexOf('electr') !== -1) { return 'electrician'; }
    if (cat.indexOf('hvac') !== -1 || cat.indexOf('air con') !== -1 || cat.indexOf('cooling') !== -1) { return 'HVAC engineer'; }
    if (cat.indexOf('roofing') !== -1 || cat.indexOf('roof') !== -1) { return 'roofer'; }
    if (cat.indexOf('renovat') !== -1 || cat.indexOf('builder') !== -1) { return 'builder'; }
    if (cat.indexOf('window') !== -1 || cat.indexOf('glazing') !== -1) { return 'window fitter'; }
    return 'trades engineer';
  }

  function extractClosingTime(hoursStr) {
    if (!hoursStr) { return ''; }
    var lines = String(hoursStr).split('|');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].toLowerCase().trim();
      if (line.indexOf('saturday') === 0 || line.indexOf('sunday') === 0 ||
          line.indexOf('sat:') === 0 || line.indexOf('sun:') === 0) { continue; }
      var dashIdx = line.lastIndexOf('-');
      if (dashIdx !== -1) {
        var closePart = line.substring(dashIdx + 1).trim();
        if (closePart.length > 0) { return closePart; }
      }
    }
    return '';
  }

  function isClosingBeforeSix(closingTime) {
    if (!closingTime) { return false; }
    var t = String(closingTime).toLowerCase().trim();
    var isPm = t.indexOf('pm') !== -1;
    var isAm = t.indexOf('am') !== -1;
    var digits = '';
    for (var ci = 0; ci < t.length; ci++) {
      var ch = t.charAt(ci);
      if (ch >= '0' && ch <= '9') { digits += ch; }
      else if (ch === ':') { digits += ch; }
    }
    var colonIdx = digits.indexOf(':');
    var hourStr = colonIdx !== -1 ? digits.substring(0, colonIdx) : digits;
    var hour = parseInt(hourStr, 10);
    if (isNaN(hour)) { return false; }
    if (isPm && hour !== 12) { hour = hour + 12; }
    if (isAm && hour === 12) { hour = 0; }
    return hour < 18;
  }

  function hasNoWeekendHours(hoursStr) {
    if (!hoursStr) { return false; }   // FIX F-A3: unknown != no weekend hours
    var lower = String(hoursStr).toLowerCase();
    return lower.indexOf('saturday') === -1 && lower.indexOf('sunday') === -1;
  }

  function competitorHasWeekendHours(compHoursStr) {
    if (!compHoursStr) { return false; }
    var lower = String(compHoursStr).toLowerCase();
    return lower.indexOf('saturday') !== -1 || lower.indexOf('sunday') !== -1;
  }

  function isCallComplaint(complaint) {
    if (!complaint) { return false; }
    var c = String(complaint).toLowerCase();
    // LEVER 4: widened to cover responsiveness complaints the original list
    // missed - 'engineer no-shows', 'poor appointment scheduling', 'unresponsive'.
    // DELIBERATELY NARROW. Template B's copy is call-specific ("the phone rings
    // and you miss it"), so a pricing or workmanship complaint dropped into it
    // would read as incoherent and COST replies. Words like 'wait', 'delay',
    // 'price' and 'workmanship' are excluded on purpose - those leads stay on D.
    var kw = ['call','phone','response','respons','unrespon','respond','reply',
              'answer','rang','reach','voicemail','contact','get back','get hold',
              'get through','pickup','pick up','available','message','communic',
              'follow','appointment','schedul','no-show','no show','turn up',
              'turned up','show up','showed up','never came','never turned',
              'chase','chasing','ignore','missed'];
    for (var i = 0; i < kw.length; i++) {
      if (c.indexOf(kw[i]) !== -1) { return true; }
    }
    return false;
  }

  function computeTemplateRoute(lead) {
    var gap = (lead.competitorReviews || 0) - (lead.reviewCount || 0);
    var callComplaint = lead.topComplaint && isCallComplaint(lead.topComplaint);
    // LEVER 3: a P2 lead sitting on a dominant gap still has a credible A-lite
    // story - "they are 40 reviews ahead" lands harder when you have few, not
    // fewer. Gated at 30 rather than 10 so we take the dramatic gaps without
    // dragging in micro-businesses that cannot afford the engagement. The P1
    // review threshold stays the ICP proxy everywhere else.
    var bigGap = (gap >= (cfgR.aLiteP2GapMin || 30));
    if ((lead.priority === '1' && gap >= 10) || bigGap) {
      if (callComplaint) { return 'A'; }
      if (lead.bestReviewQuote) { return 'A-v2'; }
      return 'A-lite';
    }
    if (callComplaint) { return 'B'; }
    return 'D';
  }

  function computeEmail2Route(route, hoursGap, compWeekend, closingTime) {
    if (route === 'A' || route === 'A-v2' || route === 'A-lite') {
      if (hoursGap && compWeekend && closingTime) { return 'E1'; }
      return 'E2';
    }
    return 'E3';
  }

  // F-R3 FIX: never write a leading '+' to the sheet.
  // The Sheets node writes with USER_ENTERED by default, which treats a leading
  // '+' as a formula prefix and coerces the value to a NUMBER - so the stored
  // value ('441224638888') never matched the appendOrUpdate key ('+44XXXXXXXXXX')
  // and every re-run appended duplicates instead of updating.
  // Paired with options.cellFormat = RAW on the Sheets node.
  function sheetPhone(p) { return String(p || '').replace(/^\+/, ''); }

  // F-R5/F-R6 FIX: a stable, unique match key.
  // Phone is unsuitable as a match column: 72 rows have none and 74 share one
  // with a different business. That let appendOrUpdate update the WRONG row -
  // 'C Keightley Ltd t/a BoilerCert' was overwritten by another company.
  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function rowKey(l) {
    if (l.certNumber) { return 'MCS:' + l.certNumber; }
    var dm = domainOf(l.website);
    if (dm) { return 'DOM:' + dm; }
    if (l.phoneKey) { return 'TEL:' + l.phoneKey; }
    return 'NAME:' + String(l.companyName || '').toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 40);
  }

  // Size proxy for prioritising outreach. googleMatched distinguishes a genuine
  // '0 reviews' from 'no Google data fetched yet'.
  function sizeTier(l) {
    if (!l.googleMatched) { return '0 - unknown'; }
    var n = Number(l.reviewCount) || 0;
    if (n >= 500) { return '6 - 500+'; }
    if (n >= 150) { return '5 - 150-499'; }
    if (n >= 50) { return '4 - 50-149'; }
    if (n >= 15) { return '3 - 15-49'; }
    if (n >= 5) { return '2 - 5-14'; }
    return '1 - 0-4';
  }

  // WhatsApp message — SECOND touch only, sent after the Day-2 call.
  // Deliberately contains NO performance claims or client results.
  function buildWhatsAppMessage(lead, trade, tradeScene) {
    if (lead.waSignal === 'none') { return ''; }
    var fn = lead.firstName || '';
    var name = fn ? fn.toLowerCase() : 'mate';
    var msg = 'alright ' + name + ' - tried you earlier. it was about the calls that come in while you are ' +
              tradeScene + '. no worries if now is not a good time. want me to send the 2 minute version?';
    return msg;
  }

  var routeStats = {};

  for (var i = 0; i < items.length; i++) {
    var l = items[i].json;
    if (!l || l._error || !l.companyName) { continue; }

    var tradeScene = getTradeScene(l.categories);
    var trade = getTradeLabel(l.categories);
    var closingTime = extractClosingTime(l.openingHours);
    var hoursGap = l.hoursKnown ? (isClosingBeforeSix(closingTime) || hasNoWeekendHours(l.openingHours)) : false;
    var compWeekend = competitorHasWeekendHours(l.competitorOpeningHours);
    var gap = (l.competitorReviews || 0) - (l.reviewCount || 0);
    var reviewGap = gap > 0 ? gap : 0;
    var templateRoute = computeTemplateRoute(l);
    var email2Route = computeEmail2Route(templateRoute, hoursGap, compWeekend, closingTime);

    routeStats[templateRoute] = (routeStats[templateRoute] || 0) + 1;

    results.push({ json: {
      'Company Name':             l.companyName || '',
      'City':                     l.city || '',
      'Phone':                    sheetPhone(l.phone),
      'Website':                  l.website || '',
      'First Name':               l.firstName || '',
      'Email':                    l.email || '',
      'LinkedIn URL':             l.linkedinUrl || '',
      'Google Maps URL':          l.googleMapsUrl || '',
      'Google Rating':            l.googleRating || '',
      'Review Count':             l.reviewCount || '',
      'Business Category':        l.categories || '',
      'Opening Hours':            l.openingHours || '',
      'Business Attributes':      l.businessAttributes || '',
      'Top Complaint':            l.topComplaint || '',
      'Best Review Quote':        l.bestReviewQuote || '',
      'Top Competitor':           l.competitorName || '',
      'Competitor Reviews':       l.competitorReviews || '',
      'Competitor Opening Hours': l.competitorOpeningHours || '',
      'Priority':                 l.priority || '2',
      'Template Route':           templateRoute,
      'Email 2 Route':            email2Route,
      'Hours Gap':                hoursGap ? 'TRUE' : 'FALSE',
      'Closing Time':             closingTime,
      'Trade Scene':              tradeScene,
      'Competitor Has Weekend':   compWeekend ? 'TRUE' : 'FALSE',
      'Call Prep Card':           l.callPrepCard || '',
      'LinkedIn Message':         '',
      'Status':                   'new',
      'Date Added':               today,
      'Email Sent':               '',
      'Call Status':              '',
      'LinkedIn Status':          '',
      'Notes':                    '',
      'Trade':                    trade,
      'Review Gap':               reviewGap,
      'Email Verify Status':      l.emailVerifyStatus || '',
      'Source':                   l.source || '',
      'MCS Cert Body':            l.certBody || '',
      'MCS Cert Number':          l.certNumber || '',
      'Technologies':             l.technologies || '',
      'BUS Registered':           l.busRegistered ? 'TRUE' : 'FALSE',
      'Entity Type':              l.entityType || '',
      'Email Source':             l.emailSource || '',
      'Postcode':                 l.postcode || '',
      'UK Country':               l.ukCountry || '',
      'Competitor Distance':      (l.competitorDistanceMiles === null || l.competitorDistanceMiles === undefined) ? '' : l.competitorDistanceMiles,
      'Competitor Tier':          l.competitorTier || '',
      'Emailable':                l.emailable ? 'TRUE' : 'FALSE',
      'PECR Risk':                l.pecrRisk ? 'TRUE' : 'FALSE',
      'Is Mobile':                l.isMobile ? 'TRUE' : 'FALSE',
      'WhatsApp Signal':          l.waSignal || 'none',
      'WhatsApp Number':          sheetPhone(l.waNumber),
      'WhatsApp Message':         buildWhatsAppMessage(l, trade, tradeScene),
      'WhatsApp Status':          '',
      'Row Key':                  rowKey(l),
      'Size Tier':                sizeTier(l)
    }});
  }

  if (!results.length) {
    return [{ json: { _error: 'Build CRM Row produced 0 rows' } }];
  }
  results[0].json._routeStats = JSON.stringify(routeStats);
  return results;
} catch (e) {
  return [{ json: { _error: 'Build CRM Row failed: ' + e.message } }];
}

// Turns the single {config, index, leads[]} payload into one item per lead.
try {
  var t = $('🧩 Batch Input').first().json || {};
  var leads = t.leads || [];
  if (!leads.length) { return [{ json: { _error: 'Batch Input carried 0 leads' } }]; }
  var out = [];
  for (var i = 0; i < leads.length; i++) { out.push({ json: leads[i] }); }
  return out;
} catch (e) {
  return [{ json: { _error: 'Unpack Leads failed: ' + e.message } }];
}

// Returns COUNTS ONLY to the parent. Never return the enriched records -
// that would put the whole dataset back into the parent's memory, which is
// the exact problem this architecture exists to avoid (F-R1).
try {
  var items = $input.all();
  var routes = {}, prios = {}, written = 0;
  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    written++;
    var rt = r['Template Route'] || '(none)';
    routes[rt] = (routes[rt] || 0) + 1;
    var pr = r['Priority'] || '(none)';
    prios[pr] = (prios[pr] || 0) + 1;
  }
  var t = {};
  try { t = $('🧩 Batch Input').first().json || {}; } catch (e) { t = {}; }
  return [{ json: {
    batchIndex: t.batchIndex === undefined ? null : t.batchIndex,
    leadsIn: (t.leads || []).length,
    rowsWritten: written,
    byTemplateRoute: routes,
    byPriority: prios
  }}];
} catch (e) {
  return [{ json: { _error: 'Return Summary failed: ' + e.message } }];
}

// Builds ONE combined prompt per eligible lead: review analysis + call prep card
// in a single Claude call. Two separate calls doubled cost and latency for no gain.
// The API key is NOT handled here - the HTTP node uses the n8n 'anthropicApi'
// credential, so no secret ever lands in execution data.
try {
  var cfg = $('⚙️ Config').first().json;
  var nLow = cfg.reviewsLowCount || 5;
  var nHigh = cfg.reviewsHighCount || 3;
  var maxCalls = cfg.maxClaudeCalls || 0;

  var items = $input.all();
  var results = [];
  var called = 0;
  var stats = { eligible: 0, prompted: 0, withReviewText: 0, capped: false };

  for (var i = 0; i < items.length; i++) {
    var lead = items[i].json;
    if (!lead || lead._error) { results.push({ json: lead }); continue; }

    var eligible = (lead.priority === '1');
    if (eligible) { stats.eligible++; }
    var underCap = (maxCalls === 0) || (called < maxCalls);
    if (eligible && !underCap) { stats.capped = true; }

    var prompt = '';
    if (eligible && underCap) {
      // Reviews sorted by rating: lowest carry the complaint (Templates A/B),
      // highest carry the quote (A-v2). Sending only lows would kill A-v2.
      var reviews = lead.reviews || [];
      var rated = [];
      for (var r = 0; r < reviews.length; r++) {
        var rv = reviews[r];
        if (rv && rv.text && String(rv.text).length > 15) {
          rated.push({ stars: Number(rv.stars) || 3, text: String(rv.text).trim() });
        }
      }
      rated.sort(function(a, b) { return a.stars - b.stars; });
      var chosen = [];
      for (var lo = 0; lo < rated.length && lo < nLow; lo++) { chosen.push(rated[lo]); }
      for (var hi = rated.length - 1; hi >= 0 && chosen.length < (nLow + nHigh); hi--) {
        if (chosen.indexOf(rated[hi]) === -1) { chosen.push(rated[hi]); }
      }

      var reviewBlock = 'No review text available.';
      if (chosen.length >= 2) {
        var lines = [];
        for (var c = 0; c < chosen.length; c++) {
          lines.push((c + 1) + '. [' + chosen[c].stars + ' stars] ' + chosen[c].text);
        }
        reviewBlock = 'Reviews (lowest-rated first, highest-rated last):\n' + lines.join('\n');
        stats.withReviewText++;
      }

      var ctx = [];
      ctx.push('Company: ' + (lead.companyName || '') + ' in ' + (lead.city || ''));
      if (lead.categories) { ctx.push('Trade: ' + lead.categories); }
      if (lead.googleRating > 0) { ctx.push('Rating: ' + lead.googleRating + '/5 (' + lead.reviewCount + ' reviews)'); }
      if (lead.certBody) { ctx.push('MCS certified via ' + lead.certBody + ' (' + (lead.technologies || 'renewables') + ')'); }
      if (lead.busRegistered) { ctx.push('Registered for the Boiler Upgrade Scheme - fields grant enquiries worth 7500 GBP each'); }
      if (lead.openingHours) { ctx.push('Opening hours: ' + lead.openingHours); }
      if (lead.competitorName) {
        var gap = (lead.competitorReviews || 0) - (lead.reviewCount || 0);
        ctx.push('Nearest comparable competitor: ' + lead.competitorName + ' (' +
                 lead.competitorReviews + ' reviews, ' + (gap > 0 ? gap + ' ahead' : 'similar') +
                 (lead.competitorDistanceMiles ? ', ' + lead.competitorDistanceMiles + ' miles away' : '') + ')');
      }

      prompt = 'You analyse a UK solar or heat pump installer for a cold outreach campaign.\n\n' +
        ctx.join('\n') + '\n\n' + reviewBlock + '\n\n' +
        'Return ONLY a valid JSON object, no markdown and no code fences, with exactly these five string fields:\n' +
        'topComplaint: the most mentioned complaint in 6-12 words, or "" if there is no review text or no clear issue\n' +
        'topPraise: what customers most often praise in 6-12 words, or ""\n' +
        'reviewSentiment: positive, mixed, negative, or "" if no review text\n' +
        'bestReviewQuote: the strongest positive customer quote, under 20 words, or ""\n' +
        'callPrepCard: exactly 2 sentences for a salesperson about to ring them. Sentence 1: a specific opening referencing something real about their business. Sentence 2: pre-handle the likely UK tradesperson objection ("I already have enough work" or "I have wasted money on agencies before"). Trades language only, no jargon, no mention of AI or automation, and do not invent statistics or client results.';

      called++;
      stats.prompted++;
    }

    // Drop raw review text once the prompt is built (memory).
    var clean = {};
    var keys = Object.keys(lead);
    for (var k = 0; k < keys.length; k++) {
      if (keys[k] !== 'reviews') { clean[keys[k]] = lead[keys[k]]; }
    }
    clean.topComplaint = '';
    clean.topPraise = '';
    clean.reviewSentiment = '';
    clean.bestReviewQuote = '';
    clean.callPrepCard = '';
    clean._claudePrompt = prompt;
    results.push({ json: clean });
  }

  if (results.length) { results[0].json._claudePrepStats = stats; }
  return results;
} catch (e) {
  return [{ json: { _error: 'Prep Claude Prompt failed: ' + e.message } }];
}

// Runs once per item so $('🔀 Needs Claude').item pairs the API response back to
// its lead. A failed or unparseable response leaves the five fields empty - the
// lead still flows through and simply routes to a weaker template.
try {
  var lead = $('🔀 Needs Claude').item.json;
  var out = {};
  var keys = Object.keys(lead);
  for (var k = 0; k < keys.length; k++) {
    if (keys[k] !== '_claudePrompt') { out[keys[k]] = lead[keys[k]]; }
  }

  var resp = $json;
  var txt = '';
  try { txt = resp.content[0].text.trim(); } catch (e) { txt = ''; }

  if (!txt) {
    out._claudeError = 'empty or failed response';
    return { json: out };
  }

  if (txt.indexOf('```') === 0) {
    var nl = txt.indexOf('\n');
    if (nl !== -1) { txt = txt.substring(nl + 1); }
    var lf = txt.lastIndexOf('```');
    if (lf !== -1) { txt = txt.substring(0, lf); }
    txt = txt.trim();
  }

  try {
    var p = JSON.parse(txt);
    out.topComplaint    = p.topComplaint    || '';
    out.topPraise       = p.topPraise       || '';
    out.reviewSentiment = p.reviewSentiment || '';
    out.bestReviewQuote = p.bestReviewQuote || '';
    out.callPrepCard    = p.callPrepCard    || '';
  } catch (parseErr) {
    out._claudeError = 'unparseable JSON: ' + parseErr.message;
  }

  return { json: out };
} catch (e) {
  return { json: { _error: 'Parse Claude Result failed: ' + e.message } };
}

// Stage 3a (prep) - decide which MCS rows need a Google place lookup and build
// the Apify actor input. The actual HTTP call happens in the shared Apify
// Runner sub-workflow, because Code nodes on this n8n version cannot make
// outbound HTTP calls at all (bug F-R15). Only HTTP Request nodes can.
try {
  var config = $('⚙️ Config').first().json;
  var limit = config.apifyLookupLimit || 0;

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }

  // Only rows with no Google data and enough identity to resolve a place.
  var needing = [];
  for (var n = 0; n < leads.length; n++) {
    var L = leads[n];
    if (!L.googleMatched && L.companyName && L.postcode) { needing.push(L); }
  }
  if (limit > 0 && needing.length > limit) { needing = needing.slice(0, limit); }

  var searchStrings = [];
  for (var s = 0; s < needing.length; s++) {
    searchStrings.push(needing[s].companyName + ' ' + needing[s].postcode);
  }

  return [{ json: {
    _needLookup: searchStrings.length > 0,
    _attempted: searchStrings.length,
    actorInput: {
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: 1,
      language: 'en',
      includeWebResults: false,
      includeReviews: false
    }
  }}];
} catch (e) {
  return [{ json: { _needLookup: false, _attempted: 0, _prepError: e.message, actorInput: {} } }];
}

// Stage 3a (merge) - fold the Apify place results back onto the leads.
// Emits _lookupStats.matchRate === GATE 1 (needs >= 70%).
try {
  var leadItems = $('🔓 Unpack Leads').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json && !leadItems[i].json._error) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Place Data got 0 leads' } }]; }

  var attempted = 0;
  try { attempted = $('📍 Prep Place Lookup').first().json._attempted || 0; } catch (eA) { }

  // The false branch of the IF reaches this node without the runner having run.
  var places = [];
  var runStatus = 'not-run';
  try {
    var r = $('📍 Apify Lookup Run').first().json;
    if (r && r.items && r.items.length) { places = r.items; }
    if (r && r.status) { runStatus = r.status; }
  } catch (eB) { runStatus = 'not-run'; }

  // Rebuild the query->lead map deterministically (same rule as the prep node).
  var byQuery = {};
  for (var m = 0; m < leads.length; m++) {
    var Lm = leads[m];
    if (!Lm.googleMatched && Lm.companyName && Lm.postcode) {
      byQuery[(Lm.companyName + ' ' + Lm.postcode).toLowerCase()] = Lm;
    }
  }

  var matched = 0;
  for (var pl = 0; pl < places.length; pl++) {
    var pp = places[pl];
    if (!pp) { continue; }
    var target = byQuery[String(pp.searchString || '').toLowerCase()];
    if (!target) { continue; }
    if (pp.permanentlyClosed) { continue; }

    var hrs = '';
    if (pp.openingHours && pp.openingHours.length) {
      var hp = [];
      for (var h = 0; h < pp.openingHours.length; h++) {
        var oh = pp.openingHours[h];
        if (!oh) { continue; }
        if (oh.day && oh.hours) { hp.push(oh.day + ': ' + oh.hours); }
        else if (typeof oh === 'string') { hp.push(oh); }
      }
      hrs = hp.join(' | ');
    }

    var attrs = [];
    if (pp.additionalInfo) {
      var secs = Object.keys(pp.additionalInfo);
      for (var a = 0; a < secs.length; a++) {
        var sec = pp.additionalInfo[secs[a]];
        if (!sec || typeof sec !== 'object') { continue; }
        var sk = Object.keys(sec);
        for (var s2 = 0; s2 < sk.length; s2++) {
          if (sec[sk[s2]] === true) { attrs.push(sk[s2]); }
        }
      }
    }

    target.googleRating = pp.totalScore || 0;
    target.reviewCount = pp.reviewsCount || 0;
    target.googleMapsUrl = pp.url || '';
    target.googleMatched = true;
    if (hrs) { target.openingHours = hrs; target.hoursKnown = true; }
    if (attrs.length) { target.businessAttributes = attrs.join(', '); }
    if (!target.website && pp.website) { target.website = pp.website; }
    if (pp.location) {
      if (target.latitude === null || target.latitude === undefined) { target.latitude = pp.location.lat; }
      if (target.longitude === null || target.longitude === undefined) { target.longitude = pp.location.lng; }
    }
    matched++;
  }

  var results = [];
  for (var r2 = 0; r2 < leads.length; r2++) { results.push({ json: leads[r2] }); }
  results[0].json._lookupStats = {
    attempted: attempted,
    matched: matched,
    placesReturned: places.length,
    apifyRunStatus: runStatus,
    matchRate: attempted ? Math.round((matched / attempted) * 1000) / 10 : null,
    gate1Pass: attempted ? ((matched / attempted) >= 0.7) : null,
    note: 'GATE 1 - needs >= 70%'
  };
  return results;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔓 Unpack Leads').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._lookupStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Place Data failed: ' + e.message } }];
}

// Stage 5 (prep) - choose which leads get review TEXT scraped, and build the
// Apify actor input. The HTTP call itself runs in the shared Apify Runner.
//
// WHY THIS EXISTS: the Tier-1 place lookup runs includeReviews:false, so it
// returns review COUNTS but no review TEXT. Without text, Claude can never
// produce topComplaint or bestReviewQuote - which means Template A and A-v2 can
// NEVER fire and every lead is permanently capped at A-lite or D. This is the
// single biggest lever on reply rate.
//
// COST (Apify pay-per-event): $0.007 actor start + $0.004 per place +
// $0.0005 per review. At maxReviews 20 that is ~$0.014 per lead.
try {
  var cfg = $('⚙️ Config').first().json;
  var limit = cfg.apifyReviewLimit || 0;
  var maxRev = cfg.maxReviews || 20;
  var sortBy = cfg.reviewsSort || 'lowestRanking';

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }

  // Priority-1 only. P2 leads never reach the A-family, so their reviews would
  // be paid for and never used.
  var needing = [];
  for (var n = 0; n < leads.length; n++) {
    var L = leads[n];
    if (L.priority === '1' && L.companyName && L.postcode && (L.reviewCount || 0) > 0) {
      needing.push(L);
    }
  }
  if (limit > 0 && needing.length > limit) { needing = needing.slice(0, limit); }

  var searchStrings = [];
  for (var s = 0; s < needing.length; s++) {
    searchStrings.push(needing[s].companyName + ' ' + needing[s].postcode);
  }

  return [{ json: {
    _needReviews: searchStrings.length > 0,
    _attempted: searchStrings.length,
    _reviewsSort: sortBy,
    actorInput: {
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: 1,
      language: 'en',
      includeWebResults: false,
      includeReviews: true,
      maxReviews: maxRev,
      reviewsSort: sortBy
    }
  }}];
} catch (e) {
  return [{ json: { _needReviews: false, _attempted: 0, _prepError: e.message, actorInput: {} } }];
}

// Stage 5 (merge) - attach review text to the leads it belongs to.
try {
  var leadItems = $('🎯 ICP Score').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json && !leadItems[i].json._error) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Review Data got 0 leads' } }]; }

  var attempted = 0;
  var sortBy = 'lowestRanking';
  try {
    var prep = $('📝 Prep Review Scrape').first().json;
    attempted = prep._attempted || 0;
    sortBy = prep._reviewsSort || sortBy;
  } catch (eA) { }

  var places = [];
  var runStatus = 'not-run';
  try {
    var r = $('📝 Apify Review Run').first().json;
    if (r && r.items && r.items.length) { places = r.items; }
    if (r && r.status) { runStatus = r.status; }
  } catch (eB) { runStatus = 'not-run'; }

  // Same selection rule as the prep node, so the keys line up.
  var byQuery = {};
  for (var m = 0; m < leads.length; m++) {
    var Lm = leads[m];
    if (Lm.priority === '1' && Lm.companyName && Lm.postcode && (Lm.reviewCount || 0) > 0) {
      byQuery[(Lm.companyName + ' ' + Lm.postcode).toLowerCase()] = Lm;
    }
  }

  var matched = 0, totalReviews = 0, withText = 0;
  for (var pl = 0; pl < places.length; pl++) {
    var pp = places[pl];
    if (!pp) { continue; }
    var target = byQuery[String(pp.searchString || '').toLowerCase()];
    if (!target) { continue; }
    matched++;

    var revs = [];
    var src = pp.reviews || [];
    for (var r3 = 0; r3 < src.length; r3++) {
      var rv = src[r3];
      if (!rv) { continue; }
      var txt = rv.text || rv.textTranslated || '';
      if (!txt) { continue; }
      revs.push({ stars: Number(rv.stars) || 0, text: String(txt) });
    }
    if (revs.length) {
      target.reviews = revs;
      totalReviews += revs.length;
      withText++;
    }
    // Refresh counts while we are here - this place was scraped again anyway.
    if (pp.reviewsCount) { target.reviewCount = pp.reviewsCount; }
    if (pp.totalScore) { target.googleRating = pp.totalScore; }
  }

  var out = [];
  for (var z = 0; z < leads.length; z++) { out.push({ json: leads[z] }); }
  out[0].json._reviewScrapeStats = {
    attempted: attempted,
    matched: matched,
    placesReturned: places.length,
    apifyRunStatus: runStatus,
    leadsWithReviewText: withText,
    reviewsFetched: totalReviews,
    matchRate: attempted ? Math.round((matched / attempted) * 1000) / 10 : null,
    estCostUsd: Math.round((0.007 + (matched * 0.004) + (totalReviews * 0.0005)) * 100) / 100,
    reviewsSort: sortBy
  };
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🎯 ICP Score').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._reviewScrapeStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Review Data failed: ' + e.message } }];
}

// Stage 9 (prep) - queue one item per UNIQUE email for ZeroBounce.
// Gated by cfg.verifyEnabled (a plain boolean, NOT a secret). The API key lives
// in the 'ZeroBounce API' credential, never in config. Turn verifyEnabled on
// only once that credential holds a real key.
// Free tier is 100 verifications/month - maxVerifyCalls caps the run.
try {
  var cfg = $('⚙️ Config').first().json;
  var enabled = (cfg.verifyEnabled === true);
  var maxCalls = cfg.maxVerifyCalls || 0;

  var items = $input.all();
  var out = [];
  var seen = {};
  var n = 0;

  if (enabled) {
    for (var i = 0; i < items.length; i++) {
      var lead = items[i].json;
      if (!lead || lead._error) { continue; }
      var email = String(lead.email || '').toLowerCase();
      if (!email) { continue; }
      if (seen[email]) { continue; }   // never pay twice for the same address
      if (maxCalls > 0 && n >= maxCalls) { break; }
      seen[email] = true;
      n++;
      out.push({ json: { _email: email, _needVerify: true } });
    }
  }

  if (!out.length) { return [{ json: { _needVerify: false, _queued: 0 } }]; }
  return out;
} catch (e) {
  return [{ json: { _needVerify: false, _queued: 0, _prepError: e.message } }];
}

// Stage 9 (merge) - apply ZeroBounce verdicts. Emits GATE 3.
// Clears invalid/spamtrap/abuse/do_not_mail so they can never be emailed.
// Keeps valid, catch-all and unknown.
try {
  var leadItems = $('🔍 Merge Enrich').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Verify got 0 leads' } }]; }

  // The false branch of the IF reaches this node without the HTTP call running.
  var byEmail = {};
  var checked = 0;
  try {
    var res = $('✅ ZeroBounce Validate').all();
    for (var r = 0; r < res.length; r++) {
      var v = res[r].json;
      if (!v || !v.address) { continue; }
      byEmail[String(v.address).toLowerCase()] = String(v.status || '').toLowerCase();
      checked++;
    }
  } catch (eB) { }

  var stats = { withEmail: 0, checked: checked, valid: 0, catchAll: 0, unknown: 0,
                invalid: 0, cleared: 0, unverified: 0 };

  var out = [];
  for (var k = 0; k < leads.length; k++) {
    var lead = leads[k];
    var email = lead.email || '';
    var status = 'no-email';

    if (email) {
      stats.withEmail++;
      var s = byEmail[String(email).toLowerCase()];
      if (s) {
        status = s;
        if (s === 'valid') { stats.valid++; }
        else if (s === 'catch-all') { stats.catchAll++; }
        else if (s === 'unknown') { stats.unknown++; }
        if (s === 'invalid' || s === 'spamtrap' || s === 'abuse' || s === 'do_not_mail') {
          stats.invalid++;
          stats.cleared++;
          email = '';
        }
      } else {
        status = 'unverified';
        stats.unverified++;
      }
    }

    lead.email = email;
    lead.emailVerifyStatus = status;
    out.push({ json: lead });
  }

  stats.invalidRate = checked ? Math.round((stats.invalid / checked) * 1000) / 10 : null;
  stats.gate3Pass = checked ? ((stats.invalid / checked) < 0.05) : null;
  stats.note = 'GATE 3 - needs < 5% invalid. Over 10% means re-pull the MCS snapshot.';
  out[0].json._verifyStats = stats;
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔍 Merge Enrich').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._verifyStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Verify failed: ' + e.message } }];
}

// Stage 8 (prep) - queue Instantly Lead Finder lookups, RESCOPED.
// v2 called Instantly for every lead with a website, including P2. With MCS
// supplying an email for 100% of its rows, that is mostly wasted credit.
// Called only where it adds something:
//   P1 + generic MCS email (info@)  -> yes, want a named contact
//   P1 + personal MCS email          -> no
//   Maps-sourced, no email at all    -> yes, only route to an email
//   P2 with an MCS email             -> no
// Gated by cfg.enrichEnabled (plain boolean, NOT a secret). The key lives in
// the 'Instantly API' credential.
try {
  var cfg = $('⚙️ Config').first().json;
  var enabled = (cfg.enrichEnabled === true);
  var maxCalls = cfg.maxInstantlyCalls || 0;

  var GENERIC = ['info','sales','enquiries','enquiry','admin','contact','hello',
                 'office','accounts','mail','support','team','service','post','general'];
  function localPart(e) {
    var s = String(e || '');
    var at = s.indexOf('@');
    return at > -1 ? s.substring(0, at).toLowerCase() : '';
  }
  function isGeneric(e) {
    var lp = localPart(e);
    if (!lp) { return true; }
    for (var i = 0; i < GENERIC.length; i++) { if (lp === GENERIC[i]) { return true; } }
    return false;
  }
  function domainOf(w) {
    var d = String(w || '').toLowerCase();
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }

  var items = $input.all();
  var out = [];
  var n = 0;

  if (enabled) {
    for (var i = 0; i < items.length; i++) {
      var lead = items[i].json;
      if (!lead || lead._error) { continue; }
      var email = lead.email || '';
      var isP1 = (lead.priority === '1');

      var wantCall = false;
      if (!email && lead.website) { wantCall = true; }
      else if (isP1 && email && isGeneric(email) && lead.website) { wantCall = true; }
      if (!wantCall) { continue; }

      if (maxCalls > 0 && n >= maxCalls) { break; }
      n++;
      out.push({ json: { _needEnrich: true, _key: lead._key || '', _domain: domainOf(lead.website) } });
    }
  }

  if (!out.length) { return [{ json: { _needEnrich: false, _queued: 0 } }]; }
  return out;
} catch (e) {
  return [{ json: { _needEnrich: false, _queued: 0, _prepError: e.message } }];
}

// Stage 8 (merge) - fold Instantly results back, then derive a first name from
// a personal email local-part wherever Instantly did not supply one, so the
// greeting fallback fires less often.
try {
  var leadItems = $('🔗 Merge Claude').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Enrich got 0 leads' } }]; }

  var ownerTitles = ['owner','director','founder','manager','ceo','md','managing director','partner'];
  var GENERIC = ['info','sales','enquiries','enquiry','admin','contact','hello',
                 'office','accounts','mail','support','team','service','post','general'];
  function localPart(e) {
    var s = String(e || '');
    var at = s.indexOf('@');
    return at > -1 ? s.substring(0, at).toLowerCase() : '';
  }
  function isGeneric(e) {
    var lp = localPart(e);
    if (!lp) { return true; }
    for (var g = 0; g < GENERIC.length; g++) { if (lp === GENERIC[g]) { return true; } }
    return false;
  }
  function nameFromEmail(e) {
    var lp = localPart(e);
    if (!lp || isGeneric(e)) { return ''; }
    var first = lp.split(/[._-]/)[0];
    if (!first || first.length < 2 || first.length > 14) { return ''; }
    if (!/^[a-z]+$/.test(first)) { return ''; }
    return first.charAt(0).toUpperCase() + first.substring(1);
  }

  var stats = { called: 0, ok: 0, failed: 0, nameFromEmail: 0 };

  // Pair responses to queued leads by position - the HTTP node emits exactly one
  // output item per input item, in order.
  var byKey = {};
  try {
    var prep = $('🔍 Prep Enrich').all();
    var resp = $('🔍 Instantly Search').all();
    for (var p = 0; p < prep.length && p < resp.length; p++) {
      var pk = prep[p].json._key;
      if (!pk || prep[p].json._needEnrich !== true) { continue; }
      stats.called++;
      var response = resp[p].json;
      if (!response || response.error) { stats.failed++; continue; }

      var people = [];
      if (Array.isArray(response.data)) { people = response.data; }
      else if (Array.isArray(response.results)) { people = response.results; }
      else if (Array.isArray(response)) { people = response; }
      if (!people.length) { continue; }

      var best = null;
      for (var j = 0; j < people.length && !best; j++) {
        var title = String(people[j].title || people[j].job_title || '').toLowerCase();
        for (var t = 0; t < ownerTitles.length; t++) {
          if (title.indexOf(ownerTitles[t]) !== -1) { best = people[j]; break; }
        }
      }
      if (!best) { best = people[0]; }
      byKey[pk] = best;
      stats.ok++;
    }
  } catch (eR) { }

  var out = [];
  for (var k = 0; k < leads.length; k++) {
    var lead = leads[k];
    var firstName = lead.firstName || '';
    var email = lead.email || '';
    var linkedinUrl = lead.linkedinUrl || '';

    var hit = byKey[lead._key];
    if (hit) {
      var fn = hit.first_name || hit.firstName || '';
      if (fn) { firstName = fn; }
      var fe = hit.email || '';
      if (fe && (!email || isGeneric(email))) { email = fe; lead.emailSource = 'instantly'; }
      if (!linkedinUrl) { linkedinUrl = hit.linkedin_url || hit.linkedinUrl || hit.linkedin || ''; }
    }

    if (!firstName && email) {
      var derived = nameFromEmail(email);
      if (derived) { firstName = derived; stats.nameFromEmail++; }
    }

    lead.firstName = firstName;
    lead.email = email;
    lead.linkedinUrl = linkedinUrl;
    if (!lead.emailSource && email) { lead.emailSource = 'mcs'; }
    out.push({ json: lead });
  }

  out[0].json._enrichStats = stats;
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔗 Merge Claude').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._enrichStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Enrich failed: ' + e.message } }];
}

// PLUTIOLABS LEAD SCRAPER v3 — CONFIG
// All client/run-specific values live here. Nothing hardcoded downstream.
try {
  // SUB-WORKFLOW MODE: when the parent invokes this workflow it passes its own
  // config in the payload. Returning it here means every downstream
  // $('⚙️ Config') reference keeps working unchanged, and the PARENT stays the
  // single source of truth - no config drift between parent and child.
  try {
    var incoming = $('🧩 Batch Input').first().json;
    if (incoming && incoming.config) { return [{ json: incoming.config }]; }
  } catch (subErr) { /* not running as a sub-workflow */ }

  return [{
    json: {
      // ---- API keys (fill before running enrichment stages) ----
      claudeApiKey:     'REPLACE_WITH_CLAUDE_API_KEY',
      apifyApiKey:      'REPLACE_WITH_APIFY_API_KEY',
      instantlyApiKey:  'REPLACE_WITH_INSTANTLY_API_KEY',
      zerobounceApiKey: 'REPLACE_WITH_ZEROBOUNCE_API_KEY',

      // ---- Storage ----
      sheetsId:          'YOUR_SCRAPER_SHEET_ID',
      sheetsTabName:     'Outreach CRM',
      sheetsSnapshotTab: 'MCS Snapshot',

      // ---- MCS source (Stage 1a) ----
      mcsIndexUrl:     'https://findcertifiedinstallers.co.uk/api/index.json',
      mcsInstallersUrl:'https://findcertifiedinstallers.co.uk/api/installers.json',

      // ---- Niche scope (Stage 1b) ----
      // MCS technologies that map to our solar + heat pump niche.
      mcsTechScope: ['solar_pv','ashp','battery','wshp','solar_thermal','eahp'],

      // PECR: only Ltd/LLP/plc are corporate subscribers (cold email allowed).
      emailOnlyLtd: true,

      // MEMORY CAP. The first full run (5,620 leads) crashed the n8n Cloud
      // instance at 47s with 0 nodes persisted - n8n retains every node's
      // input AND output, so a ~20-node chain holds ~20 copies of the dataset.
      // Keep this capped until the sub-workflow batching is built. 0 = unlimited.
      maxLeads: 500,
      // Offset into the filtered MCS list, for running sequential slices.
      // NOTE: slicing shrinks the competitor pool (F-R2) - a sliced run
      // produces WORSE competitor matching than one full-pool run. Only use
      // offsets once the parent/child batching shares one global index.
      leadOffset: 0,
      // Targeted repair: process ONLY these MCS certification numbers.
      // Empty array = normal full/capped run.
      onlyCerts: [],

      // ---- Google Maps discovery (Stage 1c — same niche, catches
      //      umbrella-scheme / lapsed / commercial installers MCS cannot see) ----
      apifyMaxResultsPerSearch: 40,
      // v2 polled 180 x 30s = 90 min inside a Code node and would hit the
      // n8n execution timeout, losing the entire scrape. Bounded here.
      apifyMaxPollMinutes: 20,
      // GATE 1 pilot cap: only look up this many MCS leads. Set to 0 for unlimited
      // once the match rate is proven >= 70%.
      apifyLookupLimit: 100,
      includeReviews: true,
      maxReviews: 20,
      ukCities: ['London','Manchester','Birmingham','Leeds'],
      ukKeywords: [
        'solar panel installer {city}',
        'solar PV installer {city}',
        'solar energy company {city}',
        'solar panel company {city}',
        'solar battery storage installer {city}',
        'solar installation {city}',
        'heat pump installer {city}',
        'air source heat pump installer {city}',
        'ground source heat pump installer {city}',
        'heat pump engineer {city}'
      ],

      // ---- Competitor match (Stage 3b) ----
      // Banded, NOT max: an unbanded pick returns median gap 224-554,
      // which names a national installer as a "local competitor".
      competitorRadiusMiles:   10,
      competitorRadiusFallback:15,
      competitorGapMin:        10,
      competitorGapMax:        150,

      // ---- ICP scoring (Stage 4) ----
      minReviewsForP1: 8,

      // ---- Review analysis (Stage 5/6) ----
      // Pass the LOWEST-rated reviews to Claude. Complaints live in 1-3 star
      // reviews; "most relevant" skews 5-star and topComplaint comes back empty.
      // Send BOTH ends of the rating distribution to Claude in one call:
      // lowest-rated carry the complaint (Template A/B), highest-rated carry
      // the quote (Template A-v2). Sending only lowest would kill A-v2.
      reviewsLowCount: 5,
      reviewsHighCount: 3,
      // GATE 2 pilot cap on Claude calls. Set to 0 for unlimited after measuring.
      maxClaudeCalls: 100,
      // Instantly is now only called where it adds something (see Enrich node).
      maxInstantlyCalls: 0,
      // GATE 3 pilot cap. ZeroBounce free tier is 100/month - check your plan
      // before raising this for a 5,000-lead run.
      maxVerifyCalls: 200
    }
  }];
} catch (e) {
  return [{ json: { _error: 'Config failed: ' + e.message } }];
}

// Stage 1a — split the MCS installers array into one item per lead.
try {
  var payload = $input.first().json;
  var rows = (payload && payload.installers) ? payload.installers : [];

  var idx = {};
  try { idx = $('📡 Fetch MCS Index').first().json || {}; } catch (e) { idx = {}; }
  var generatedAt = idx.generated_at || '';

  if (!rows.length) {
    return [{ json: { _error: 'MCS fetch returned no installers', _count: 0 } }];
  }

  var out = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    r.source = 'mcs';
    r.mcsGeneratedAt = generatedAt;
    out.push({ json: r });
  }
  return out;
} catch (e) {
  return [{ json: { _error: 'Split MCS failed: ' + e.message } }];
}

// Stage 1b — scope filter + the 5 mandatory fixes from the 2026-08-15 data audit.
try {
  var cfg = $('⚙️ Config').first().json;
  var scope = cfg.mcsTechScope || [];
  var ltdOnly = cfg.emailOnlyLtd !== false;
  var maxLeads = cfg.maxLeads || 0;
  var onlyCerts = cfg.onlyCerts || [];
  var leadOffset = cfg.leadOffset || 0;
  var matchedIdx = 0;
  var items = $input.all();

  var FREE = ['gmail.com','hotmail.com','hotmail.co.uk','yahoo.com','yahoo.co.uk',
              'outlook.com','icloud.com','btinternet.com','live.co.uk','aol.com',
              'sky.com','msn.com','me.com'];

  // Scotland / Wales / NI postcode areas. `region` is England-only — never filter on it.
  var SCOT = ['AB','DD','DG','EH','FK','G','HS','IV','KA','KW','KY','ML','PA','PH','TD','ZE'];
  var WALES = ['CF','LD','LL','NP','SA'];

  function pcArea(pc) {
    var m = String(pc || '').toUpperCase().match(/^[A-Z]{1,2}/);
    return m ? m[0] : '';
  }
  function country(pc) {
    var a = pcArea(pc);
    if (a === 'BT') return 'Northern Ireland';
    if (SCOT.indexOf(a) !== -1) return 'Scotland';
    if (WALES.indexOf(a) !== -1) return 'Wales';
    return 'England';
  }
  function isLtd(name) {
    var n = String(name || '').toLowerCase().replace(/\.+$/, '').trim();
    return /\b(ltd|limited|llp|plc)$/.test(n);
  }
  function fixSite(w) {
    var s = String(w || '').trim();
    if (!s) return '';
    if (/\s/.test(s)) return '';                 // embedded space = malformed
    if (!/\.[a-z]{2,}/i.test(s)) return '';       // no TLD = malformed
    if (!/^https?:\/\//i.test(s)) s = 'https://' + s;  // FIX: 83.2% lack a scheme
    return s.replace(/\/+$/, '');
  }
  function normPhone(p) {
    var d = String(p || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) d = d.substring(2);
    if (d.indexOf('0') === 0) d = d.substring(1);
    // F-R7 FIX: preserve non-standard lengths. Returning '' for anything that
    // wasn't exactly 10 digits destroyed 23 working phone numbers AND created
    // blank match keys, which let appendOrUpdate overwrite one business's row
    // with another's (F-R6 - lost 'C Keightley Ltd t/a BoilerCert').
    return d.length >= 7 ? d : '';
  }
  // v2's normalizer emits +44 format. Must match or the merge dedupe silently fails.
  function e164(k) { return k ? '+44' + k : ''; }

  var out = [];
  var stats = { seen: 0, outOfScope: 0, notLtd: 0, badGeo: 0, kept: 0,
                pecrRisk: 0, badSite: 0, badPhone: 0, skippedByOffset: 0 };

  for (var i = 0; i < items.length; i++) {
    if (maxLeads > 0 && out.length >= maxLeads) { stats.capped = true; break; }
    var r = items[i].json;
    if (!r || r._error) { continue; }
    stats.seen++;

    // Targeted repair mode: process only these certification numbers.
    if (onlyCerts.length && onlyCerts.indexOf(r.certification_number) === -1) { continue; }

    var techs = r.technologies || [];
    var inScope = false;
    for (var t = 0; t < techs.length; t++) {
      if (scope.indexOf(techs[t]) !== -1) { inScope = true; break; }
    }
    if (!inScope) { stats.outOfScope++; continue; }

    // FIX: drop rows outside the UK bounding box (2 known junk rows)
    var lat = Number(r.latitude), lon = Number(r.longitude);
    if (!(lat >= 49.8 && lat <= 60.9 && lon >= -8.7 && lon <= 1.9)) {
      stats.badGeo++; continue;
    }

    // Offset slicing: skip the first N in-scope leads.
    matchedIdx++;
    if (leadOffset > 0 && matchedIdx <= leadOffset) { stats.skippedByOffset++; continue; }

    var ltd = isLtd(r.name);
    if (ltdOnly && !ltd) { stats.notLtd++; }

    var site = fixSite(r.website);
    if (r.website && !site) { stats.badSite++; }

    var phone = normPhone(r.telephone);
    if (r.telephone && !phone) { stats.badPhone++; }

    var email = String(r.email || '').trim().toLowerCase();
    var emailDomain = email.indexOf('@') > -1 ? email.split('@')[1] : '';
    var freeMailbox = FREE.indexOf(emailDomain) !== -1;
    var emailValid = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email);

    // PECR: sole-trader signal = free mailbox AND no Ltd suffix -> phone only
    var pecrRisk = (!ltd && freeMailbox);
    if (pecrRisk) { stats.pecrRisk++; }

    var emailable = emailValid && !pecrRisk && (!ltdOnly || ltd);

    stats.kept++;
    out.push({ json: {
      source: 'mcs',
      mcsGeneratedAt: r.mcsGeneratedAt || '',
      companyName: r.name,
      certNumber: r.certification_number,
      certBody: r.certification_body,
      technologies: techs.join(', '),
      busRegistered: !!r.bus_registered,
      address: r.address,
      postcode: r.postcode,
      town: r.town,
      county: r.county,
      country: country(r.postcode),
      latitude: lat,
      longitude: lon,
      phone: e164(phone),
      phoneKey: phone,
      phoneRaw: r.telephone || '',
      email: email,
      emailValid: emailValid,
      emailFreeMailbox: freeMailbox,
      website: site,
      googleRating: (r.google_rating === null || r.google_rating === undefined) ? null : Number(r.google_rating),
      reviewCount: (r.google_review_count === null || r.google_review_count === undefined) ? null : Number(r.google_review_count),
      googleMatched: (r.google_review_count !== null && r.google_review_count !== undefined),
      entityType: ltd ? 'ltd' : 'unknown',
      pecrRisk: pecrRisk,
      emailable: emailable,
      mcsPageUrl: r.page_url || ''
    }});
  }

  if (!out.length) {
    return [{ json: { _error: 'MCS filter produced 0 leads', _stats: stats } }];
  }
  out[0].json._stats = stats;
  return out;
} catch (e) {
  return [{ json: { _error: 'MCS filter failed: ' + e.message } }];
}

// Diagnostic — prints the real funnel so we can see what we actually have
// before spending a penny on Apify / Claude / Instantly.
try {
  var items = $input.all();
  var s = { total: 0, emailable: 0, ltd: 0, pecrRisk: 0, withWebsite: 0,
            withGoogleData: 0, p1Ready: 0, busRegistered: 0 };
  var byCountry = {}, byCertBody = {}, byTech = {};
  var minRev = ($('⚙️ Config').first().json.minReviewsForP1) || 8;
  var filterStats = null;

  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    if (r._stats) { filterStats = r._stats; }
    s.total++;
    if (r.emailable) { s.emailable++; }
    if (r.entityType === 'ltd') { s.ltd++; }
    if (r.pecrRisk) { s.pecrRisk++; }
    if (r.website) { s.withWebsite++; }
    if (r.googleMatched) { s.withGoogleData++; }
    if (r.busRegistered) { s.busRegistered++; }
    if (r.website && r.reviewCount !== null && r.reviewCount >= minRev) { s.p1Ready++; }

    byCountry[r.country] = (byCountry[r.country] || 0) + 1;
    byCertBody[r.certBody] = (byCertBody[r.certBody] || 0) + 1;
    var techs = String(r.technologies || '').split(', ');
    for (var t = 0; t < techs.length; t++) {
      if (techs[t]) { byTech[techs[t]] = (byTech[techs[t]] || 0) + 1; }
    }
  }

  return [{ json: {
    _summary: 'MCS Stage 1a/1b complete',
    mcsGeneratedAt: items.length ? (items[0].json.mcsGeneratedAt || 'unknown') : 'unknown',
    counts: s,
    filterStats: filterStats,
    byCountry: byCountry,
    byCertBody: byCertBody,
    byTechnology: byTech,
    note: 'p1Ready counts only leads whose review data MCS already carries (~47%). Apify Tier-1 lookup fills the rest.'
  }}];
} catch (e) {
  return [{ json: { _error: 'Summary failed: ' + e.message } }];
}

// Stage 1c — Google Maps keyword discovery (ported from v2 + 4 fixes).
// Purpose: catch umbrella-scheme / lapsed / commercial installers MCS cannot see.
var config = $('⚙️ Config').first().json;
var apifyKey = config.apifyApiKey || '';
var cities = config.ukCities || [];
var keywords = config.ukKeywords || [];
var maxResults = config.apifyMaxResultsPerSearch || 40;
var inclReviews = config.includeReviews !== false;
var maxRev = config.maxReviews || 20;
var maxPolls = (config.apifyMaxPollMinutes || 20) * 2;  // FIX: 30s per poll, bounded
var ukLeads = [];

// FIX: graceful skip so the MCS branch still runs before the Apify key exists.
if (!apifyKey || apifyKey.indexOf('REPLACE_WITH') === 0) {
  return [{ json: { _skipped: true, source: 'maps', _note: 'Apify key not set - Maps discovery skipped, MCS branch continues' } }];
}

var searchStrings = [];
for (var ci = 0; ci < cities.length; ci++) {
  for (var ki = 0; ki < keywords.length; ki++) {
    searchStrings.push(keywords[ki].replace('{city}', cities[ci]));
  }
}

try {
  var startRes = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/compass~crawler-google-places/runs?waitForFinish=0',
    headers: { 'Authorization': 'Bearer ' + apifyKey, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: maxResults,
      language: 'en',
      includeWebResults: false,
      includeReviews: inclReviews,
      maxReviews: maxRev,
      reviewsSort: 'newest'
    })
  });

  var runId = startRes.data.id;
  var datasetId = startRes.data.defaultDatasetId;

  var runStatus = 'RUNNING';
  var pollCount = 0;
  while (runStatus !== 'SUCCEEDED' && runStatus !== 'FAILED' && runStatus !== 'ABORTED' && pollCount < maxPolls) {
    await new Promise(function(done) { setTimeout(done, 30000); });
    var statusRes = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/actor-runs/' + runId,
      headers: { 'Authorization': 'Bearer ' + apifyKey }
    });
    runStatus = statusRes.data.status;
    pollCount++;
  }

  if (runStatus !== 'SUCCEEDED') {
    throw new Error('Apify run ' + runStatus + ' after ' + (pollCount * 30) + 's (ceiling ' + maxPolls + ' polls)');
  }

  var allPlaces = [];
  var offset = 0;
  var fetchDone = false;
  while (!fetchDone) {
    var batch = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items?format=json&limit=500&offset=' + offset,
      headers: { 'Authorization': 'Bearer ' + apifyKey }
    });
    if (!batch || batch.length === 0) {
      fetchDone = true;
    } else {
      for (var bi = 0; bi < batch.length; bi++) { allPlaces.push(batch[bi]); }
      fetchDone = batch.length < 500;
      offset += 500;
    }
  }

  for (var k = 0; k < allPlaces.length; k++) {
    var p = allPlaces[k];
    if (p.permanentlyClosed || p.temporarilyClosed) { continue; }
    if (!p.phone && !p.website) { continue; }

    var social = p.socialMediaLinks || {};
    var socialArr = [];
    if (Array.isArray(social)) {
      for (var mi = 0; mi < social.length; mi++) {
        var sm = social[mi];
        if (typeof sm === 'string') { socialArr.push(sm); }
        else if (sm && sm.url) { socialArr.push(sm.url); }
      }
    } else {
      var sKeys = Object.keys(social);
      for (var mj = 0; mj < sKeys.length; mj++) {
        if (social[sKeys[mj]]) { socialArr.push(social[sKeys[mj]]); }
      }
    }

    // NEW: capture published WhatsApp click-to-chat links (public, on their own listing)
    var waLink = '';
    for (var wi = 0; wi < socialArr.length; wi++) {
      var sl = String(socialArr[wi]).toLowerCase();
      if (sl.indexOf('wa.me') !== -1 || sl.indexOf('api.whatsapp.com') !== -1) {
        waLink = socialArr[wi];
        break;
      }
    }

    var hours = '';
    if (p.openingHours && p.openingHours.length) {
      var hParts = [];
      for (var hi = 0; hi < p.openingHours.length; hi++) {
        var oh = p.openingHours[hi];
        if (!oh) { continue; }
        if (oh.day && oh.hours) { hParts.push(oh.day + ': ' + oh.hours); }
        else if (typeof oh === 'string') { hParts.push(oh); }
      }
      hours = hParts.join(' | ');
    }

    var cats = p.categories ? p.categories.join(', ') : (p.categoryName || '');

    var attrs = [];
    if (p.additionalInfo) {
      var aiSections = Object.keys(p.additionalInfo);
      for (var ai = 0; ai < aiSections.length; ai++) {
        var sec = p.additionalInfo[aiSections[ai]];
        if (!sec || typeof sec !== 'object') { continue; }
        var secKeys = Object.keys(sec);
        for (var si = 0; si < secKeys.length; si++) {
          if (sec[secKeys[si]] === true) { attrs.push(secKeys[si]); }
        }
      }
    }

    var city = p.city || '';
    if (!city && p.searchString) {
      var sLower = p.searchString.toLowerCase();
      for (var cfi = 0; cfi < cities.length; cfi++) {
        if (sLower.indexOf(cities[cfi].toLowerCase()) !== -1) { city = cities[cfi]; break; }
      }
    }

    // NEW: capture coordinates — required by the geospatial competitor match.
    // v2 discarded these, which would have left every Maps lead unmatchable.
    var lat = null, lon = null;
    if (p.location) {
      lat = (p.location.lat !== undefined) ? p.location.lat : null;
      lon = (p.location.lng !== undefined) ? p.location.lng : null;
    }

    ukLeads.push({ json: {
      companyName:        p.title || '',
      city:               city,
      postcode:           p.postalCode || '',
      address:            p.address || '',
      phone:              p.phone || '',
      website:            p.website || '',
      email:              '',
      source:             'maps',
      googleRating:       p.totalScore || 0,
      reviewCount:        p.reviewsCount || 0,
      googleMapsUrl:      p.url || '',
      categories:         cats,
      openingHours:       hours,
      businessAttributes: attrs.join(', '),
      socialLinks:        socialArr.join(', '),
      waLink:             waLink,
      latitude:           lat,
      longitude:          lon,
      reviews:            p.reviews || []
    }});
  }
} catch (e) {
  return [{ json: { _skipped: true, source: 'maps', _error: 'Google Maps: ' + e.message } }];
}

return ukLeads;

// Stage 1d — reconcile MCS + Maps into ONE canonical record shape, then dedupe.
// Subsumes v2's '🔧 Normalize & Deduplicate' (same dedupe keys, single pass).
try {
  var items = $input.all();

  // FIX F-A1: MCS rows have no `categories`. Synthesise one from `technologies`
  // so v2's getTradeLabel / getTradeScene / getTradeGroup work UNCHANGED.
  var TECH_LABEL = {
    solar_pv: 'Solar panel installer', solar_thermal: 'Solar thermal installer',
    battery: 'Solar battery storage', ashp: 'Heat pump installer',
    wshp: 'Heat pump installer', eahp: 'Heat pump installer',
    gshp: 'Heat pump installer', sahp: 'Heat pump installer',
    gahp: 'Heat pump installer', biomass: 'Biomass installer',
    wind_turbine: 'Wind turbine installer', micro_chp: 'Micro CHP installer'
  };
  var TECH_ORDER = ['solar_pv','solar_thermal','battery','ashp','wshp','eahp',
                    'gshp','sahp','gahp','biomass','wind_turbine','micro_chp'];

  function techToCategories(techStr) {
    var raw = String(techStr || '').split(',');
    var have = {};
    for (var i = 0; i < raw.length; i++) {
      var t = raw[i].replace(/\s/g, '');
      if (t) { have[t] = true; }
    }
    var out = [];
    for (var o = 0; o < TECH_ORDER.length; o++) {
      var key = TECH_ORDER[o];
      if (have[key]) {
        var lab = TECH_LABEL[key];
        if (lab && out.indexOf(lab) === -1) { out.push(lab); }
      }
    }
    return out.join(', ');
  }

  function normPhone(phone) {
    var raw = String(phone || '');
    var p = '';
    for (var ci = 0; ci < raw.length; ci++) {
      var ch = raw.charAt(ci);
      if (ch >= '0' && ch <= '9') { p += ch; }
      else if (ch === '+' && p.length === 0) { p += ch; }
    }
    if (p.length < 5) { return ''; }
    if (p.charAt(0) === '+') { return p; }
    if (p.charAt(0) === '0') { return '+44' + p.substring(1); }
    if (p.length > 10 && p.substring(0, 2) === '44') { return '+' + p; }
    return p;
  }
  function phoneKeyOf(e164) {
    var d = String(e164 || '').replace(/\D/g, '');
    if (d.indexOf('44') === 0) { d = d.substring(2); }
    if (d.indexOf('0') === 0) { d = d.substring(1); }
    return d.length >= 7 ? d : '';   // F-R7: preserve non-standard lengths
  }
  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function isMob(e164) { return String(e164 || '').indexOf('+447') === 0; }

  function canonMcs(r) {
    var ph = r.phone || '';
    return {
      companyName: r.companyName || '', city: r.town || '', country: 'UK',
      ukCountry: r.country || '', postcode: r.postcode || '', county: r.county || '',
      address: r.address || '',
      phone: ph, phoneKey: r.phoneKey || phoneKeyOf(ph),
      website: r.website || '', email: r.email || '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'mcs',
      googleRating: r.googleRating || 0,
      reviewCount: (r.reviewCount === null || r.reviewCount === undefined) ? 0 : r.reviewCount,
      googleMatched: !!r.googleMatched,
      googleMapsUrl: '', categories: techToCategories(r.technologies),
      openingHours: '', hoursKnown: false,
      businessAttributes: '', socialLinks: '', reviews: [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: r.certNumber || '', certBody: r.certBody || '',
      technologies: r.technologies || '', busRegistered: !!r.busRegistered,
      entityType: r.entityType || 'unknown', pecrRisk: !!r.pecrRisk,
      emailable: !!r.emailable, emailSource: r.email ? 'mcs' : '',
      mcsGeneratedAt: r.mcsGeneratedAt || '', mcsPageUrl: r.mcsPageUrl || '',
      isMobile: isMob(ph), waLink: ''
    };
  }

  function canonMaps(r) {
    var ph = normPhone(r.phone);
    return {
      companyName: r.companyName || '', city: r.city || '', country: 'UK',
      ukCountry: '', postcode: r.postcode || '', county: '', address: r.address || '',
      phone: ph, phoneKey: phoneKeyOf(ph),
      website: r.website || '', email: '',
      firstName: '', ownerName: '', linkedinUrl: '',
      source: 'maps',
      googleRating: r.googleRating || 0, reviewCount: r.reviewCount || 0,
      googleMatched: true,
      googleMapsUrl: r.googleMapsUrl || '', categories: r.categories || '',
      openingHours: r.openingHours || '', hoursKnown: !!r.openingHours,
      businessAttributes: r.businessAttributes || '', socialLinks: r.socialLinks || '',
      reviews: r.reviews || [],
      latitude: r.latitude, longitude: r.longitude,
      certNumber: '', certBody: '', technologies: '', busRegistered: false,
      entityType: 'unknown', pecrRisk: false, emailable: false, emailSource: '',
      mcsGeneratedAt: '', mcsPageUrl: '',
      isMobile: isMob(ph), waLink: r.waLink || ''
    };
  }

  var byPhone = {}, byDomain = {};
  var out = [];
  var stats = { mcsIn: 0, mapsIn: 0, mapsSkipped: 0, merged: 0, mapsNetNew: 0, dropped: 0 };

  // Pass 1 — MCS is the base list.
  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error || r._skipped) {
      if (r && r._skipped) { stats.mapsSkipped++; }
      continue;
    }
    if (r.source !== 'mcs') { continue; }
    stats.mcsIn++;
    var c = canonMcs(r);
    if (!c.companyName) { stats.dropped++; continue; }
    out.push(c);
    if (c.phoneKey) { byPhone[c.phoneKey] = c; }
    var d = domainOf(c.website);
    if (d) { byDomain[d] = c; }
  }

  // Pass 2 — Maps rows either enrich an existing MCS row or become net-new leads.
  for (var j = 0; j < items.length; j++) {
    var m = items[j].json;
    if (!m || m._error || m._skipped) { continue; }
    if (m.source !== 'maps') { continue; }
    stats.mapsIn++;

    var cm = canonMaps(m);
    if (!cm.companyName) { stats.dropped++; continue; }

    var dm = domainOf(cm.website);
    var hit = null;
    if (cm.phoneKey && byPhone[cm.phoneKey]) { hit = byPhone[cm.phoneKey]; }
    else if (dm && byDomain[dm]) { hit = byDomain[dm]; }

    if (hit) {
      // Precedence: MCS wins identity/contact, Maps wins Google intelligence.
      hit.source = 'both';
      hit.googleRating = cm.googleRating || hit.googleRating;
      hit.reviewCount = cm.reviewCount || hit.reviewCount;
      hit.googleMatched = true;
      hit.googleMapsUrl = cm.googleMapsUrl || hit.googleMapsUrl;
      hit.openingHours = cm.openingHours || hit.openingHours;
      hit.hoursKnown = hit.hoursKnown || cm.hoursKnown;
      hit.businessAttributes = cm.businessAttributes || hit.businessAttributes;
      hit.socialLinks = cm.socialLinks || hit.socialLinks;
      hit.reviews = (cm.reviews && cm.reviews.length) ? cm.reviews : hit.reviews;
      hit.waLink = hit.waLink || cm.waLink;
      if (!hit.categories) { hit.categories = cm.categories; }
      if (!hit.website) { hit.website = cm.website; }
      if (hit.latitude === null || hit.latitude === undefined) { hit.latitude = cm.latitude; }
      if (hit.longitude === null || hit.longitude === undefined) { hit.longitude = cm.longitude; }
      stats.merged++;
    } else {
      out.push(cm);
      if (cm.phoneKey) { byPhone[cm.phoneKey] = cm; }
      if (dm) { byDomain[dm] = cm; }
      stats.mapsNetNew++;
    }
  }

  // WhatsApp signal (step 15). Public sources only — never a registration check.
  for (var k = 0; k < out.length; k++) {
    var o = out[k];
    if (o.waLink) { o.waSignal = 'wa-link'; o.waNumber = o.phone; }
    else if (o.isMobile) { o.waSignal = 'mobile'; o.waNumber = o.phone; }
    else { o.waSignal = 'none'; o.waNumber = ''; }
  }

  // 'both' first — richest records lead the export.
  out.sort(function(a, b) {
    var rank = { both: 0, mcs: 1, maps: 2 };
    return (rank[a.source] || 3) - (rank[b.source] || 3);
  });

  if (!out.length) {
    return [{ json: { _error: 'Reconcile produced 0 leads', _stats: stats } }];
  }

  var results = [];
  for (var z = 0; z < out.length; z++) { results.push({ json: out[z] }); }
  results[0].json._reconcileStats = stats;
  return results;
} catch (e) {
  return [{ json: { _error: 'Reconcile failed: ' + e.message } }];
}

// Stage 3b — REWRITTEN. Geospatial join over the merged list.
// v2 grouped by lowercased city STRING and took the max-review peer. That breaks
// on merged data (MCS towns like 'Tonbridge and Malling' never match 'London')
// and an unbanded max names a national installer as a 'local competitor'
// (measured median gap 224-554, not credible to a tradesman).
try {
  var cfg = $('⚙️ Config').first().json;
  var R1 = cfg.competitorRadiusMiles || 10;
  var R2 = cfg.competitorRadiusFallback || 15;
  var GMIN = cfg.competitorGapMin || 10;
  var GMAX = cfg.competitorGapMax || 150;

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Competitor Match got 0 leads' } }]; }

  function tradeGroup(categories) {
    if (!categories) { return 'general'; }
    var c = String(categories).toLowerCase();
    if (c.indexOf('solar') !== -1 || c.indexOf('panel') !== -1) { return 'solar'; }
    if (c.indexOf('heat pump') !== -1 || c.indexOf('heatpump') !== -1) { return 'heatpump'; }
    if (c.indexOf('boiler') !== -1 || c.indexOf('heating') !== -1 || c.indexOf('plumb') !== -1) { return 'heating'; }
    if (c.indexOf('insul') !== -1) { return 'insulation'; }
    if (c.indexOf('hvac') !== -1 || c.indexOf('air con') !== -1 || c.indexOf('cooling') !== -1) { return 'hvac'; }
    if (c.indexOf('electr') !== -1) { return 'electrical'; }
    if (c.indexOf('roofing') !== -1 || c.indexOf('roof') !== -1) { return 'roofing'; }
    if (c.indexOf('renovat') !== -1 || c.indexOf('builder') !== -1) { return 'renovation'; }
    if (c.indexOf('window') !== -1 || c.indexOf('glazing') !== -1) { return 'glazing'; }
    return 'general';
  }

  // Grid index (~0.25 deg cells) so this stays O(n) rather than O(n^2) at 5k leads.
  var CELL = 0.25;
  var grid = {};
  var pool = [];

  // F-R2 FIX: match against the parent's GLOBAL index when running as a
  // sub-workflow, so a 500-lead batch still sees the whole 5,600-lead pool.
  // Measured: full pool matches ~100% of eligible leads, a 500-lead slice 48.6%.
  // Falls back to the local batch when running standalone.
  var poolSrc = leads;
  var usingGlobalIndex = false;
  try {
    var bi = $('🧩 Batch Input').first().json;
    if (bi && bi.index && bi.index.length) { poolSrc = bi.index; usingGlobalIndex = true; }
  } catch (e) { /* standalone */ }

  // Identity key so a lead never matches itself in the global index
  // (object identity does not hold across the parent/child boundary).
  function idKey(x) {
    if (x.certNumber) { return 'MCS:' + x.certNumber; }
    if (x.key) { return x.key; }
    return 'NM:' + String(x.companyName || '').toLowerCase();
  }
  for (var q = 0; q < leads.length; q++) {
    leads[q]._tg = tradeGroup(leads[q].categories);
    leads[q]._key = idKey(leads[q]);
  }

  for (var p = 0; p < poolSrc.length; p++) {
    var L = poolSrc[p];
    L._tg = tradeGroup(L.categories);
    L._key = idKey(L);
    if (typeof L.latitude !== 'number' || typeof L.longitude !== 'number') { continue; }
    if (!L.reviewCount || L.reviewCount <= 0) { continue; }
    var gk = Math.round(L.latitude / CELL) + ':' + Math.round(L.longitude / CELL);
    if (!grid[gk]) { grid[gk] = []; }
    grid[gk].push(L);
    pool.push(L);
  }

  function milesBetween(a, b) {
    var dLat = (b.latitude - a.latitude) * 69;
    var dLon = (b.longitude - a.longitude) * 69 * Math.cos(a.latitude * Math.PI / 180);
    return Math.sqrt(dLat * dLat + dLon * dLon);
  }

  function candidates(L, miles) {
    var found = [];
    var cy = Math.round(L.latitude / CELL);
    var cx = Math.round(L.longitude / CELL);
    var span = Math.ceil(miles / 12) + 1;
    for (var dy = -span; dy <= span; dy++) {
      for (var dx = -span; dx <= span; dx++) {
        var cellList = grid[(cy + dy) + ':' + (cx + dx)];
        if (!cellList) { continue; }
        for (var z = 0; z < cellList.length; z++) {
          var o = cellList[z];
          if (o === L) { continue; }
          if (o._key && L._key && o._key === L._key) { continue; }
          if (milesBetween(L, o) <= miles) { found.push(o); }
        }
      }
    }
    return found;
  }

  function pick(L, miles, sameTrade) {
    var cands = candidates(L, miles);
    var best = null;
    for (var c = 0; c < cands.length; c++) {
      var o = cands[c];
      if (sameTrade && o._tg !== L._tg) { continue; }
      var gap = (o.reviewCount || 0) - (L.reviewCount || 0);
      if (gap < GMIN || gap > GMAX) { continue; }
      if (!best || o.reviewCount > best.reviewCount) { best = o; }
    }
    return best;
  }

  var stats = { poolSize: pool.length, usingGlobalIndex: usingGlobalIndex,
                matched: 0, tier1: 0, tier2: 0, tier3: 0, none: 0 };

  for (var j = 0; j < leads.length; j++) {
    var lead = leads[j];
    var comp = null;
    var tier = '';

    if (typeof lead.latitude === 'number' && typeof lead.longitude === 'number' && lead.reviewCount > 0) {
      comp = pick(lead, R1, true);
      if (comp) { tier = 'same-trade-' + R1 + 'mi'; stats.tier1++; }
      if (!comp) {
        comp = pick(lead, R2, true);
        if (comp) { tier = 'same-trade-' + R2 + 'mi'; stats.tier2++; }
      }
      if (!comp) {
        comp = pick(lead, R1, false);
        if (comp) { tier = 'any-trade-' + R1 + 'mi'; stats.tier3++; }
      }
    }

    if (comp) {
      lead.competitorName = comp.companyName || '';
      lead.competitorRating = comp.googleRating || 0;
      lead.competitorReviews = comp.reviewCount || 0;
      lead.competitorOpeningHours = comp.openingHours || '';
      lead.competitorDistanceMiles = Math.round(milesBetween(lead, comp) * 10) / 10;
      lead.competitorTier = tier;
      stats.matched++;
    } else {
      lead.competitorName = '';
      lead.competitorRating = 0;
      lead.competitorReviews = 0;
      lead.competitorOpeningHours = '';
      lead.competitorDistanceMiles = null;
      lead.competitorTier = 'none';
      stats.none++;
    }
    delete lead._tg;
  }

  var results = [];
  for (var r = 0; r < leads.length; r++) { results.push({ json: leads[r] }); }
  results[0].json._competitorStats = stats;
  return results;
} catch (e) {
  return [{ json: { _error: 'Competitor Match failed: ' + e.message } }];
}

// Stage 4 — ICP scoring.
// Two changes vs v2:
//  1. review threshold 10 -> configurable (8). Dataset p25 is 6, median 17;
//     10 was discarding a usable band.
//  2. 'has contact' now accepts an MCS email, not just a website. The website
//     requirement only ever existed because Instantly needs a domain.
try {
  var cfg = $('⚙️ Config').first().json;
  var minRev = cfg.minReviewsForP1 || 8;

  var items = $input.all();
  var results = [];
  var stats = { p1: 0, p2: 0, noContact: 0 };

  for (var i = 0; i < items.length; i++) {
    var lead = items[i].json;
    if (!lead || lead._error) { results.push({ json: lead }); continue; }

    var hasContact = !!(lead.website || lead.email);
    if (!hasContact) { stats.noContact++; }

    var priority = (hasContact && (lead.reviewCount || 0) >= minRev) ? '1' : '2';
    if (priority === '1') { stats.p1++; } else { stats.p2++; }

    lead.priority = priority;
    results.push({ json: lead });
  }

  results.sort(function(a, b) {
    var ap = (a.json && a.json.priority) ? a.json.priority : '9';
    var bp = (b.json && b.json.priority) ? b.json.priority : '9';
    return ap.localeCompare(bp);
  });

  if (results.length) { results[0].json._icpStats = stats; }
  return results;
} catch (e) {
  return [{ json: { _error: 'ICP Score failed: ' + e.message } }];
}

// Stage 10 — assemble the CRM row. Output keys ARE the Sheet column headers
// (the Sheets node uses autoMapInputData), so these strings must match exactly.
//
// Changes vs v2:
//  1. F-A3 fix: unknown opening hours no longer report 'Hours Gap = TRUE'.
//  2. LinkedIn message generation removed. It carried HARDCODED FABRICATED
//     client results (barJobs/barWeeks/barCity). The WhatsApp replacement makes
//     NO performance claims until a real case study exists.
//  3. New MCS + WhatsApp columns appended.
try {
  var items = $input.all();
  var today = new Date().toISOString().split('T')[0];
  // Read defensively - this node has never needed config before (LEVER 3).
  var cfgR = {};
  try { cfgR = $('⚙️ Config').first().json || {}; } catch (eCfg) { }
  var results = [];

  function getTradeScene(categories) {
    if (!categories) { return 'out on a job'; }
    var cat = String(categories).toLowerCase();
    if (cat.indexOf('solar') !== -1 || cat.indexOf('panel') !== -1) { return 'on a roof fitting panels'; }
    if (cat.indexOf('heat pump') !== -1 || cat.indexOf('heatpump') !== -1) { return 'commissioning a heat pump system'; }
    if (cat.indexOf('boiler') !== -1) { return 'in a plant room fitting a boiler'; }
    if (cat.indexOf('heating') !== -1 || cat.indexOf('plumb') !== -1) { return 'in a plant room fitting a boiler'; }
    if (cat.indexOf('insul') !== -1) { return 'installing insulation in a loft'; }
    if (cat.indexOf('electr') !== -1) { return 'on a job wiring a property'; }
    if (cat.indexOf('hvac') !== -1 || cat.indexOf('air con') !== -1 || cat.indexOf('cooling') !== -1) { return 'fitting an air conditioning unit'; }
    if (cat.indexOf('renovat') !== -1 || cat.indexOf('builder') !== -1) { return 'on site running a job'; }
    if (cat.indexOf('window') !== -1 || cat.indexOf('glazing') !== -1) { return 'on a job fitting windows'; }
    if (cat.indexOf('roofing') !== -1 || cat.indexOf('roof') !== -1) { return 'up on a roof'; }
    return 'out on a job';
  }

  function getTradeLabel(categories) {
    if (!categories) { return 'trade'; }
    var cat = String(categories).toLowerCase();
    if (cat.indexOf('solar') !== -1 || cat.indexOf('panel') !== -1) { return 'solar installer'; }
    if (cat.indexOf('heat pump') !== -1 || cat.indexOf('heatpump') !== -1) { return 'heat pump installer'; }
    if (cat.indexOf('boiler') !== -1) { return 'boiler engineer'; }
    if (cat.indexOf('heating') !== -1 || cat.indexOf('plumb') !== -1) { return 'heating engineer'; }
    if (cat.indexOf('insul') !== -1) { return 'insulation installer'; }
    if (cat.indexOf('electr') !== -1) { return 'electrician'; }
    if (cat.indexOf('hvac') !== -1 || cat.indexOf('air con') !== -1 || cat.indexOf('cooling') !== -1) { return 'HVAC engineer'; }
    if (cat.indexOf('roofing') !== -1 || cat.indexOf('roof') !== -1) { return 'roofer'; }
    if (cat.indexOf('renovat') !== -1 || cat.indexOf('builder') !== -1) { return 'builder'; }
    if (cat.indexOf('window') !== -1 || cat.indexOf('glazing') !== -1) { return 'window fitter'; }
    return 'trades engineer';
  }

  function extractClosingTime(hoursStr) {
    if (!hoursStr) { return ''; }
    var lines = String(hoursStr).split('|');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].toLowerCase().trim();
      if (line.indexOf('saturday') === 0 || line.indexOf('sunday') === 0 ||
          line.indexOf('sat:') === 0 || line.indexOf('sun:') === 0) { continue; }
      var dashIdx = line.lastIndexOf('-');
      if (dashIdx !== -1) {
        var closePart = line.substring(dashIdx + 1).trim();
        if (closePart.length > 0) { return closePart; }
      }
    }
    return '';
  }

  function isClosingBeforeSix(closingTime) {
    if (!closingTime) { return false; }
    var t = String(closingTime).toLowerCase().trim();
    var isPm = t.indexOf('pm') !== -1;
    var isAm = t.indexOf('am') !== -1;
    var digits = '';
    for (var ci = 0; ci < t.length; ci++) {
      var ch = t.charAt(ci);
      if (ch >= '0' && ch <= '9') { digits += ch; }
      else if (ch === ':') { digits += ch; }
    }
    var colonIdx = digits.indexOf(':');
    var hourStr = colonIdx !== -1 ? digits.substring(0, colonIdx) : digits;
    var hour = parseInt(hourStr, 10);
    if (isNaN(hour)) { return false; }
    if (isPm && hour !== 12) { hour = hour + 12; }
    if (isAm && hour === 12) { hour = 0; }
    return hour < 18;
  }

  function hasNoWeekendHours(hoursStr) {
    if (!hoursStr) { return false; }   // FIX F-A3: unknown != no weekend hours
    var lower = String(hoursStr).toLowerCase();
    return lower.indexOf('saturday') === -1 && lower.indexOf('sunday') === -1;
  }

  function competitorHasWeekendHours(compHoursStr) {
    if (!compHoursStr) { return false; }
    var lower = String(compHoursStr).toLowerCase();
    return lower.indexOf('saturday') !== -1 || lower.indexOf('sunday') !== -1;
  }

  function isCallComplaint(complaint) {
    if (!complaint) { return false; }
    var c = String(complaint).toLowerCase();
    // LEVER 4: widened to cover responsiveness complaints the original list
    // missed - 'engineer no-shows', 'poor appointment scheduling', 'unresponsive'.
    // DELIBERATELY NARROW. Template B's copy is call-specific ("the phone rings
    // and you miss it"), so a pricing or workmanship complaint dropped into it
    // would read as incoherent and COST replies. Words like 'wait', 'delay',
    // 'price' and 'workmanship' are excluded on purpose - those leads stay on D.
    var kw = ['call','phone','response','respons','unrespon','respond','reply',
              'answer','rang','reach','voicemail','contact','get back','get hold',
              'get through','pickup','pick up','available','message','communic',
              'follow','appointment','schedul','no-show','no show','turn up',
              'turned up','show up','showed up','never came','never turned',
              'chase','chasing','ignore','missed'];
    for (var i = 0; i < kw.length; i++) {
      if (c.indexOf(kw[i]) !== -1) { return true; }
    }
    return false;
  }

  function computeTemplateRoute(lead) {
    var gap = (lead.competitorReviews || 0) - (lead.reviewCount || 0);
    var callComplaint = lead.topComplaint && isCallComplaint(lead.topComplaint);
    // LEVER 3: a P2 lead sitting on a dominant gap still has a credible A-lite
    // story - "they are 40 reviews ahead" lands harder when you have few, not
    // fewer. Gated at 30 rather than 10 so we take the dramatic gaps without
    // dragging in micro-businesses that cannot afford the engagement. The P1
    // review threshold stays the ICP proxy everywhere else.
    var bigGap = (gap >= (cfgR.aLiteP2GapMin || 30));
    if ((lead.priority === '1' && gap >= 10) || bigGap) {
      if (callComplaint) { return 'A'; }
      if (lead.bestReviewQuote) { return 'A-v2'; }
      return 'A-lite';
    }
    if (callComplaint) { return 'B'; }
    return 'D';
  }

  function computeEmail2Route(route, hoursGap, compWeekend, closingTime) {
    if (route === 'A' || route === 'A-v2' || route === 'A-lite') {
      if (hoursGap && compWeekend && closingTime) { return 'E1'; }
      return 'E2';
    }
    return 'E3';
  }

  // F-R3 FIX: never write a leading '+' to the sheet.
  // The Sheets node writes with USER_ENTERED by default, which treats a leading
  // '+' as a formula prefix and coerces the value to a NUMBER - so the stored
  // value ('441224638888') never matched the appendOrUpdate key ('+44XXXXXXXXXX')
  // and every re-run appended duplicates instead of updating.
  // Paired with options.cellFormat = RAW on the Sheets node.
  function sheetPhone(p) { return String(p || '').replace(/^\+/, ''); }

  // F-R5/F-R6 FIX: a stable, unique match key.
  // Phone is unsuitable as a match column: 72 rows have none and 74 share one
  // with a different business. That let appendOrUpdate update the WRONG row -
  // 'C Keightley Ltd t/a BoilerCert' was overwritten by another company.
  function domainOf(w) {
    var d = String(w || '').toLowerCase().trim();
    if (!d) { return ''; }
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }
  function rowKey(l) {
    if (l.certNumber) { return 'MCS:' + l.certNumber; }
    var dm = domainOf(l.website);
    if (dm) { return 'DOM:' + dm; }
    if (l.phoneKey) { return 'TEL:' + l.phoneKey; }
    return 'NAME:' + String(l.companyName || '').toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 40);
  }

  // Size proxy for prioritising outreach. googleMatched distinguishes a genuine
  // '0 reviews' from 'no Google data fetched yet'.
  function sizeTier(l) {
    if (!l.googleMatched) { return '0 - unknown'; }
    var n = Number(l.reviewCount) || 0;
    if (n >= 500) { return '6 - 500+'; }
    if (n >= 150) { return '5 - 150-499'; }
    if (n >= 50) { return '4 - 50-149'; }
    if (n >= 15) { return '3 - 15-49'; }
    if (n >= 5) { return '2 - 5-14'; }
    return '1 - 0-4';
  }

  // WhatsApp message — SECOND touch only, sent after the Day-2 call.
  // Deliberately contains NO performance claims or client results.
  function buildWhatsAppMessage(lead, trade, tradeScene) {
    if (lead.waSignal === 'none') { return ''; }
    var fn = lead.firstName || '';
    var name = fn ? fn.toLowerCase() : 'mate';
    var msg = 'alright ' + name + ' - tried you earlier. it was about the calls that come in while you are ' +
              tradeScene + '. no worries if now is not a good time. want me to send the 2 minute version?';
    return msg;
  }

  var routeStats = {};

  for (var i = 0; i < items.length; i++) {
    var l = items[i].json;
    if (!l || l._error || !l.companyName) { continue; }

    var tradeScene = getTradeScene(l.categories);
    var trade = getTradeLabel(l.categories);
    var closingTime = extractClosingTime(l.openingHours);
    var hoursGap = l.hoursKnown ? (isClosingBeforeSix(closingTime) || hasNoWeekendHours(l.openingHours)) : false;
    var compWeekend = competitorHasWeekendHours(l.competitorOpeningHours);
    var gap = (l.competitorReviews || 0) - (l.reviewCount || 0);
    var reviewGap = gap > 0 ? gap : 0;
    var templateRoute = computeTemplateRoute(l);
    var email2Route = computeEmail2Route(templateRoute, hoursGap, compWeekend, closingTime);

    routeStats[templateRoute] = (routeStats[templateRoute] || 0) + 1;

    results.push({ json: {
      'Company Name':             l.companyName || '',
      'City':                     l.city || '',
      'Phone':                    sheetPhone(l.phone),
      'Website':                  l.website || '',
      'First Name':               l.firstName || '',
      'Email':                    l.email || '',
      'LinkedIn URL':             l.linkedinUrl || '',
      'Google Maps URL':          l.googleMapsUrl || '',
      'Google Rating':            l.googleRating || '',
      'Review Count':             l.reviewCount || '',
      'Business Category':        l.categories || '',
      'Opening Hours':            l.openingHours || '',
      'Business Attributes':      l.businessAttributes || '',
      'Top Complaint':            l.topComplaint || '',
      'Best Review Quote':        l.bestReviewQuote || '',
      'Top Competitor':           l.competitorName || '',
      'Competitor Reviews':       l.competitorReviews || '',
      'Competitor Opening Hours': l.competitorOpeningHours || '',
      'Priority':                 l.priority || '2',
      'Template Route':           templateRoute,
      'Email 2 Route':            email2Route,
      'Hours Gap':                hoursGap ? 'TRUE' : 'FALSE',
      'Closing Time':             closingTime,
      'Trade Scene':              tradeScene,
      'Competitor Has Weekend':   compWeekend ? 'TRUE' : 'FALSE',
      'Call Prep Card':           l.callPrepCard || '',
      'LinkedIn Message':         '',
      'Status':                   'new',
      'Date Added':               today,
      'Email Sent':               '',
      'Call Status':              '',
      'LinkedIn Status':          '',
      'Notes':                    '',
      'Trade':                    trade,
      'Review Gap':               reviewGap,
      'Email Verify Status':      l.emailVerifyStatus || '',
      'Source':                   l.source || '',
      'MCS Cert Body':            l.certBody || '',
      'MCS Cert Number':          l.certNumber || '',
      'Technologies':             l.technologies || '',
      'BUS Registered':           l.busRegistered ? 'TRUE' : 'FALSE',
      'Entity Type':              l.entityType || '',
      'Email Source':             l.emailSource || '',
      'Postcode':                 l.postcode || '',
      'UK Country':               l.ukCountry || '',
      'Competitor Distance':      (l.competitorDistanceMiles === null || l.competitorDistanceMiles === undefined) ? '' : l.competitorDistanceMiles,
      'Competitor Tier':          l.competitorTier || '',
      'Emailable':                l.emailable ? 'TRUE' : 'FALSE',
      'PECR Risk':                l.pecrRisk ? 'TRUE' : 'FALSE',
      'Is Mobile':                l.isMobile ? 'TRUE' : 'FALSE',
      'WhatsApp Signal':          l.waSignal || 'none',
      'WhatsApp Number':          sheetPhone(l.waNumber),
      'WhatsApp Message':         buildWhatsAppMessage(l, trade, tradeScene),
      'WhatsApp Status':          '',
      'Row Key':                  rowKey(l),
      'Size Tier':                sizeTier(l)
    }});
  }

  if (!results.length) {
    return [{ json: { _error: 'Build CRM Row produced 0 rows' } }];
  }
  results[0].json._routeStats = JSON.stringify(routeStats);
  return results;
} catch (e) {
  return [{ json: { _error: 'Build CRM Row failed: ' + e.message } }];
}

// Turns the single {config, index, leads[]} payload into one item per lead.
try {
  var t = $('🧩 Batch Input').first().json || {};
  var leads = t.leads || [];
  if (!leads.length) { return [{ json: { _error: 'Batch Input carried 0 leads' } }]; }
  var out = [];
  for (var i = 0; i < leads.length; i++) { out.push({ json: leads[i] }); }
  return out;
} catch (e) {
  return [{ json: { _error: 'Unpack Leads failed: ' + e.message } }];
}

// Returns COUNTS ONLY to the parent. Never return the enriched records -
// that would put the whole dataset back into the parent's memory, which is
// the exact problem this architecture exists to avoid (F-R1).
try {
  var items = $input.all();
  var routes = {}, prios = {}, written = 0;
  for (var i = 0; i < items.length; i++) {
    var r = items[i].json;
    if (!r || r._error) { continue; }
    written++;
    var rt = r['Template Route'] || '(none)';
    routes[rt] = (routes[rt] || 0) + 1;
    var pr = r['Priority'] || '(none)';
    prios[pr] = (prios[pr] || 0) + 1;
  }
  var t = {};
  try { t = $('🧩 Batch Input').first().json || {}; } catch (e) { t = {}; }
  return [{ json: {
    batchIndex: t.batchIndex === undefined ? null : t.batchIndex,
    leadsIn: (t.leads || []).length,
    rowsWritten: written,
    byTemplateRoute: routes,
    byPriority: prios
  }}];
} catch (e) {
  return [{ json: { _error: 'Return Summary failed: ' + e.message } }];
}

// Builds ONE combined prompt per eligible lead: review analysis + call prep card
// in a single Claude call. Two separate calls doubled cost and latency for no gain.
// The API key is NOT handled here - the HTTP node uses the n8n 'anthropicApi'
// credential, so no secret ever lands in execution data.
try {
  var cfg = $('⚙️ Config').first().json;
  var nLow = cfg.reviewsLowCount || 5;
  var nHigh = cfg.reviewsHighCount || 3;
  var maxCalls = cfg.maxClaudeCalls || 0;

  var items = $input.all();
  var results = [];
  var called = 0;
  var stats = { eligible: 0, prompted: 0, withReviewText: 0, capped: false };

  for (var i = 0; i < items.length; i++) {
    var lead = items[i].json;
    if (!lead || lead._error) { results.push({ json: lead }); continue; }

    var eligible = (lead.priority === '1');
    if (eligible) { stats.eligible++; }
    var underCap = (maxCalls === 0) || (called < maxCalls);
    if (eligible && !underCap) { stats.capped = true; }

    var prompt = '';
    if (eligible && underCap) {
      // Reviews sorted by rating: lowest carry the complaint (Templates A/B),
      // highest carry the quote (A-v2). Sending only lows would kill A-v2.
      var reviews = lead.reviews || [];
      var rated = [];
      for (var r = 0; r < reviews.length; r++) {
        var rv = reviews[r];
        if (rv && rv.text && String(rv.text).length > 15) {
          rated.push({ stars: Number(rv.stars) || 3, text: String(rv.text).trim() });
        }
      }
      rated.sort(function(a, b) { return a.stars - b.stars; });
      var chosen = [];
      for (var lo = 0; lo < rated.length && lo < nLow; lo++) { chosen.push(rated[lo]); }
      for (var hi = rated.length - 1; hi >= 0 && chosen.length < (nLow + nHigh); hi--) {
        if (chosen.indexOf(rated[hi]) === -1) { chosen.push(rated[hi]); }
      }

      var reviewBlock = 'No review text available.';
      if (chosen.length >= 2) {
        var lines = [];
        for (var c = 0; c < chosen.length; c++) {
          lines.push((c + 1) + '. [' + chosen[c].stars + ' stars] ' + chosen[c].text);
        }
        reviewBlock = 'Reviews (lowest-rated first, highest-rated last):\n' + lines.join('\n');
        stats.withReviewText++;
      }

      var ctx = [];
      ctx.push('Company: ' + (lead.companyName || '') + ' in ' + (lead.city || ''));
      if (lead.categories) { ctx.push('Trade: ' + lead.categories); }
      if (lead.googleRating > 0) { ctx.push('Rating: ' + lead.googleRating + '/5 (' + lead.reviewCount + ' reviews)'); }
      if (lead.certBody) { ctx.push('MCS certified via ' + lead.certBody + ' (' + (lead.technologies || 'renewables') + ')'); }
      if (lead.busRegistered) { ctx.push('Registered for the Boiler Upgrade Scheme - fields grant enquiries worth 7500 GBP each'); }
      if (lead.openingHours) { ctx.push('Opening hours: ' + lead.openingHours); }
      if (lead.competitorName) {
        var gap = (lead.competitorReviews || 0) - (lead.reviewCount || 0);
        ctx.push('Nearest comparable competitor: ' + lead.competitorName + ' (' +
                 lead.competitorReviews + ' reviews, ' + (gap > 0 ? gap + ' ahead' : 'similar') +
                 (lead.competitorDistanceMiles ? ', ' + lead.competitorDistanceMiles + ' miles away' : '') + ')');
      }

      prompt = 'You analyse a UK solar or heat pump installer for a cold outreach campaign.\n\n' +
        ctx.join('\n') + '\n\n' + reviewBlock + '\n\n' +
        'Return ONLY a valid JSON object, no markdown and no code fences, with exactly these five string fields:\n' +
        'topComplaint: the most mentioned complaint in 6-12 words, or "" if there is no review text or no clear issue\n' +
        'topPraise: what customers most often praise in 6-12 words, or ""\n' +
        'reviewSentiment: positive, mixed, negative, or "" if no review text\n' +
        'bestReviewQuote: the strongest positive customer quote, under 20 words, or ""\n' +
        'callPrepCard: exactly 2 sentences for a salesperson about to ring them. Sentence 1: a specific opening referencing something real about their business. Sentence 2: pre-handle the likely UK tradesperson objection ("I already have enough work" or "I have wasted money on agencies before"). Trades language only, no jargon, no mention of AI or automation, and do not invent statistics or client results.';

      called++;
      stats.prompted++;
    }

    // Drop raw review text once the prompt is built (memory).
    var clean = {};
    var keys = Object.keys(lead);
    for (var k = 0; k < keys.length; k++) {
      if (keys[k] !== 'reviews') { clean[keys[k]] = lead[keys[k]]; }
    }
    clean.topComplaint = '';
    clean.topPraise = '';
    clean.reviewSentiment = '';
    clean.bestReviewQuote = '';
    clean.callPrepCard = '';
    clean._claudePrompt = prompt;
    results.push({ json: clean });
  }

  if (results.length) { results[0].json._claudePrepStats = stats; }
  return results;
} catch (e) {
  return [{ json: { _error: 'Prep Claude Prompt failed: ' + e.message } }];
}

// Runs once per item so $('🔀 Needs Claude').item pairs the API response back to
// its lead. A failed or unparseable response leaves the five fields empty - the
// lead still flows through and simply routes to a weaker template.
try {
  var lead = $('🔀 Needs Claude').item.json;
  var out = {};
  var keys = Object.keys(lead);
  for (var k = 0; k < keys.length; k++) {
    if (keys[k] !== '_claudePrompt') { out[keys[k]] = lead[keys[k]]; }
  }

  var resp = $json;
  var txt = '';
  try { txt = resp.content[0].text.trim(); } catch (e) { txt = ''; }

  if (!txt) {
    out._claudeError = 'empty or failed response';
    return { json: out };
  }

  if (txt.indexOf('```') === 0) {
    var nl = txt.indexOf('\n');
    if (nl !== -1) { txt = txt.substring(nl + 1); }
    var lf = txt.lastIndexOf('```');
    if (lf !== -1) { txt = txt.substring(0, lf); }
    txt = txt.trim();
  }

  try {
    var p = JSON.parse(txt);
    out.topComplaint    = p.topComplaint    || '';
    out.topPraise       = p.topPraise       || '';
    out.reviewSentiment = p.reviewSentiment || '';
    out.bestReviewQuote = p.bestReviewQuote || '';
    out.callPrepCard    = p.callPrepCard    || '';
  } catch (parseErr) {
    out._claudeError = 'unparseable JSON: ' + parseErr.message;
  }

  return { json: out };
} catch (e) {
  return { json: { _error: 'Parse Claude Result failed: ' + e.message } };
}

// Stage 3a (prep) - decide which MCS rows need a Google place lookup and build
// the Apify actor input. The actual HTTP call happens in the shared Apify
// Runner sub-workflow, because Code nodes on this n8n version cannot make
// outbound HTTP calls at all (bug F-R15). Only HTTP Request nodes can.
try {
  var config = $('⚙️ Config').first().json;
  var limit = config.apifyLookupLimit || 0;

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }

  // Only rows with no Google data and enough identity to resolve a place.
  var needing = [];
  for (var n = 0; n < leads.length; n++) {
    var L = leads[n];
    if (!L.googleMatched && L.companyName && L.postcode) { needing.push(L); }
  }
  if (limit > 0 && needing.length > limit) { needing = needing.slice(0, limit); }

  var searchStrings = [];
  for (var s = 0; s < needing.length; s++) {
    searchStrings.push(needing[s].companyName + ' ' + needing[s].postcode);
  }

  return [{ json: {
    _needLookup: searchStrings.length > 0,
    _attempted: searchStrings.length,
    actorInput: {
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: 1,
      language: 'en',
      includeWebResults: false,
      includeReviews: false
    }
  }}];
} catch (e) {
  return [{ json: { _needLookup: false, _attempted: 0, _prepError: e.message, actorInput: {} } }];
}

// Stage 3a (merge) - fold the Apify place results back onto the leads.
// Emits _lookupStats.matchRate === GATE 1 (needs >= 70%).
try {
  var leadItems = $('🔓 Unpack Leads').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json && !leadItems[i].json._error) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Place Data got 0 leads' } }]; }

  var attempted = 0;
  try { attempted = $('📍 Prep Place Lookup').first().json._attempted || 0; } catch (eA) { }

  // The false branch of the IF reaches this node without the runner having run.
  var places = [];
  var runStatus = 'not-run';
  try {
    var r = $('📍 Apify Lookup Run').first().json;
    if (r && r.items && r.items.length) { places = r.items; }
    if (r && r.status) { runStatus = r.status; }
  } catch (eB) { runStatus = 'not-run'; }

  // Rebuild the query->lead map deterministically (same rule as the prep node).
  var byQuery = {};
  for (var m = 0; m < leads.length; m++) {
    var Lm = leads[m];
    if (!Lm.googleMatched && Lm.companyName && Lm.postcode) {
      byQuery[(Lm.companyName + ' ' + Lm.postcode).toLowerCase()] = Lm;
    }
  }

  var matched = 0;
  for (var pl = 0; pl < places.length; pl++) {
    var pp = places[pl];
    if (!pp) { continue; }
    var target = byQuery[String(pp.searchString || '').toLowerCase()];
    if (!target) { continue; }
    if (pp.permanentlyClosed) { continue; }

    var hrs = '';
    if (pp.openingHours && pp.openingHours.length) {
      var hp = [];
      for (var h = 0; h < pp.openingHours.length; h++) {
        var oh = pp.openingHours[h];
        if (!oh) { continue; }
        if (oh.day && oh.hours) { hp.push(oh.day + ': ' + oh.hours); }
        else if (typeof oh === 'string') { hp.push(oh); }
      }
      hrs = hp.join(' | ');
    }

    var attrs = [];
    if (pp.additionalInfo) {
      var secs = Object.keys(pp.additionalInfo);
      for (var a = 0; a < secs.length; a++) {
        var sec = pp.additionalInfo[secs[a]];
        if (!sec || typeof sec !== 'object') { continue; }
        var sk = Object.keys(sec);
        for (var s2 = 0; s2 < sk.length; s2++) {
          if (sec[sk[s2]] === true) { attrs.push(sk[s2]); }
        }
      }
    }

    target.googleRating = pp.totalScore || 0;
    target.reviewCount = pp.reviewsCount || 0;
    target.googleMapsUrl = pp.url || '';
    target.googleMatched = true;
    if (hrs) { target.openingHours = hrs; target.hoursKnown = true; }
    if (attrs.length) { target.businessAttributes = attrs.join(', '); }
    if (!target.website && pp.website) { target.website = pp.website; }
    if (pp.location) {
      if (target.latitude === null || target.latitude === undefined) { target.latitude = pp.location.lat; }
      if (target.longitude === null || target.longitude === undefined) { target.longitude = pp.location.lng; }
    }
    matched++;
  }

  var results = [];
  for (var r2 = 0; r2 < leads.length; r2++) { results.push({ json: leads[r2] }); }
  results[0].json._lookupStats = {
    attempted: attempted,
    matched: matched,
    placesReturned: places.length,
    apifyRunStatus: runStatus,
    matchRate: attempted ? Math.round((matched / attempted) * 1000) / 10 : null,
    gate1Pass: attempted ? ((matched / attempted) >= 0.7) : null,
    note: 'GATE 1 - needs >= 70%'
  };
  return results;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔓 Unpack Leads').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._lookupStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Place Data failed: ' + e.message } }];
}

// Stage 5 (prep) - choose which leads get review TEXT scraped, and build the
// Apify actor input. The HTTP call itself runs in the shared Apify Runner.
//
// WHY THIS EXISTS: the Tier-1 place lookup runs includeReviews:false, so it
// returns review COUNTS but no review TEXT. Without text, Claude can never
// produce topComplaint or bestReviewQuote - which means Template A and A-v2 can
// NEVER fire and every lead is permanently capped at A-lite or D. This is the
// single biggest lever on reply rate.
//
// COST (Apify pay-per-event): $0.007 actor start + $0.004 per place +
// $0.0005 per review. At maxReviews 20 that is ~$0.014 per lead.
try {
  var cfg = $('⚙️ Config').first().json;
  var limit = cfg.apifyReviewLimit || 0;
  var maxRev = cfg.maxReviews || 20;
  var sortBy = cfg.reviewsSort || 'lowestRanking';

  var items = $input.all();
  var leads = [];
  for (var i = 0; i < items.length; i++) {
    if (items[i].json && !items[i].json._error) { leads.push(items[i].json); }
  }

  // Priority-1 only. P2 leads never reach the A-family, so their reviews would
  // be paid for and never used.
  var needing = [];
  for (var n = 0; n < leads.length; n++) {
    var L = leads[n];
    if (L.priority === '1' && L.companyName && L.postcode && (L.reviewCount || 0) > 0) {
      needing.push(L);
    }
  }
  if (limit > 0 && needing.length > limit) { needing = needing.slice(0, limit); }

  var searchStrings = [];
  for (var s = 0; s < needing.length; s++) {
    searchStrings.push(needing[s].companyName + ' ' + needing[s].postcode);
  }

  return [{ json: {
    _needReviews: searchStrings.length > 0,
    _attempted: searchStrings.length,
    _reviewsSort: sortBy,
    actorInput: {
      searchStringsArray: searchStrings,
      maxCrawledPlacesPerSearch: 1,
      language: 'en',
      includeWebResults: false,
      includeReviews: true,
      maxReviews: maxRev,
      reviewsSort: sortBy
    }
  }}];
} catch (e) {
  return [{ json: { _needReviews: false, _attempted: 0, _prepError: e.message, actorInput: {} } }];
}

// Stage 5 (merge) - attach review text to the leads it belongs to.
try {
  var leadItems = $('🎯 ICP Score').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json && !leadItems[i].json._error) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Review Data got 0 leads' } }]; }

  var attempted = 0;
  var sortBy = 'lowestRanking';
  try {
    var prep = $('📝 Prep Review Scrape').first().json;
    attempted = prep._attempted || 0;
    sortBy = prep._reviewsSort || sortBy;
  } catch (eA) { }

  var places = [];
  var runStatus = 'not-run';
  try {
    var r = $('📝 Apify Review Run').first().json;
    if (r && r.items && r.items.length) { places = r.items; }
    if (r && r.status) { runStatus = r.status; }
  } catch (eB) { runStatus = 'not-run'; }

  // Same selection rule as the prep node, so the keys line up.
  var byQuery = {};
  for (var m = 0; m < leads.length; m++) {
    var Lm = leads[m];
    if (Lm.priority === '1' && Lm.companyName && Lm.postcode && (Lm.reviewCount || 0) > 0) {
      byQuery[(Lm.companyName + ' ' + Lm.postcode).toLowerCase()] = Lm;
    }
  }

  var matched = 0, totalReviews = 0, withText = 0;
  for (var pl = 0; pl < places.length; pl++) {
    var pp = places[pl];
    if (!pp) { continue; }
    var target = byQuery[String(pp.searchString || '').toLowerCase()];
    if (!target) { continue; }
    matched++;

    var revs = [];
    var src = pp.reviews || [];
    for (var r3 = 0; r3 < src.length; r3++) {
      var rv = src[r3];
      if (!rv) { continue; }
      var txt = rv.text || rv.textTranslated || '';
      if (!txt) { continue; }
      revs.push({ stars: Number(rv.stars) || 0, text: String(txt) });
    }
    if (revs.length) {
      target.reviews = revs;
      totalReviews += revs.length;
      withText++;
    }
    // Refresh counts while we are here - this place was scraped again anyway.
    if (pp.reviewsCount) { target.reviewCount = pp.reviewsCount; }
    if (pp.totalScore) { target.googleRating = pp.totalScore; }
  }

  var out = [];
  for (var z = 0; z < leads.length; z++) { out.push({ json: leads[z] }); }
  out[0].json._reviewScrapeStats = {
    attempted: attempted,
    matched: matched,
    placesReturned: places.length,
    apifyRunStatus: runStatus,
    leadsWithReviewText: withText,
    reviewsFetched: totalReviews,
    matchRate: attempted ? Math.round((matched / attempted) * 1000) / 10 : null,
    estCostUsd: Math.round((0.007 + (matched * 0.004) + (totalReviews * 0.0005)) * 100) / 100,
    reviewsSort: sortBy
  };
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🎯 ICP Score').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._reviewScrapeStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Review Data failed: ' + e.message } }];
}

// Stage 9 (prep) - queue one item per UNIQUE email for ZeroBounce.
// Gated by cfg.verifyEnabled (a plain boolean, NOT a secret). The API key lives
// in the 'ZeroBounce API' credential, never in config. Turn verifyEnabled on
// only once that credential holds a real key.
// Free tier is 100 verifications/month - maxVerifyCalls caps the run.
try {
  var cfg = $('⚙️ Config').first().json;
  var enabled = (cfg.verifyEnabled === true);
  var maxCalls = cfg.maxVerifyCalls || 0;

  var items = $input.all();
  var out = [];
  var seen = {};
  var n = 0;

  if (enabled) {
    for (var i = 0; i < items.length; i++) {
      var lead = items[i].json;
      if (!lead || lead._error) { continue; }
      var email = String(lead.email || '').toLowerCase();
      if (!email) { continue; }
      if (seen[email]) { continue; }   // never pay twice for the same address
      if (maxCalls > 0 && n >= maxCalls) { break; }
      seen[email] = true;
      n++;
      out.push({ json: { _email: email, _needVerify: true } });
    }
  }

  if (!out.length) { return [{ json: { _needVerify: false, _queued: 0 } }]; }
  return out;
} catch (e) {
  return [{ json: { _needVerify: false, _queued: 0, _prepError: e.message } }];
}

// Stage 9 (merge) - apply ZeroBounce verdicts. Emits GATE 3.
// Clears invalid/spamtrap/abuse/do_not_mail so they can never be emailed.
// Keeps valid, catch-all and unknown.
try {
  var leadItems = $('🔍 Merge Enrich').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Verify got 0 leads' } }]; }

  // The false branch of the IF reaches this node without the HTTP call running.
  var byEmail = {};
  var checked = 0;
  try {
    var res = $('✅ ZeroBounce Validate').all();
    for (var r = 0; r < res.length; r++) {
      var v = res[r].json;
      if (!v || !v.address) { continue; }
      byEmail[String(v.address).toLowerCase()] = String(v.status || '').toLowerCase();
      checked++;
    }
  } catch (eB) { }

  var stats = { withEmail: 0, checked: checked, valid: 0, catchAll: 0, unknown: 0,
                invalid: 0, cleared: 0, unverified: 0 };

  var out = [];
  for (var k = 0; k < leads.length; k++) {
    var lead = leads[k];
    var email = lead.email || '';
    var status = 'no-email';

    if (email) {
      stats.withEmail++;
      var s = byEmail[String(email).toLowerCase()];
      if (s) {
        status = s;
        if (s === 'valid') { stats.valid++; }
        else if (s === 'catch-all') { stats.catchAll++; }
        else if (s === 'unknown') { stats.unknown++; }
        if (s === 'invalid' || s === 'spamtrap' || s === 'abuse' || s === 'do_not_mail') {
          stats.invalid++;
          stats.cleared++;
          email = '';
        }
      } else {
        status = 'unverified';
        stats.unverified++;
      }
    }

    lead.email = email;
    lead.emailVerifyStatus = status;
    out.push({ json: lead });
  }

  stats.invalidRate = checked ? Math.round((stats.invalid / checked) * 1000) / 10 : null;
  stats.gate3Pass = checked ? ((stats.invalid / checked) < 0.05) : null;
  stats.note = 'GATE 3 - needs < 5% invalid. Over 10% means re-pull the MCS snapshot.';
  out[0].json._verifyStats = stats;
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔍 Merge Enrich').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._verifyStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Verify failed: ' + e.message } }];
}

// Stage 8 (prep) - queue Instantly Lead Finder lookups, RESCOPED.
// v2 called Instantly for every lead with a website, including P2. With MCS
// supplying an email for 100% of its rows, that is mostly wasted credit.
// Called only where it adds something:
//   P1 + generic MCS email (info@)  -> yes, want a named contact
//   P1 + personal MCS email          -> no
//   Maps-sourced, no email at all    -> yes, only route to an email
//   P2 with an MCS email             -> no
// Gated by cfg.enrichEnabled (plain boolean, NOT a secret). The key lives in
// the 'Instantly API' credential.
try {
  var cfg = $('⚙️ Config').first().json;
  var enabled = (cfg.enrichEnabled === true);
  var maxCalls = cfg.maxInstantlyCalls || 0;

  var GENERIC = ['info','sales','enquiries','enquiry','admin','contact','hello',
                 'office','accounts','mail','support','team','service','post','general'];
  function localPart(e) {
    var s = String(e || '');
    var at = s.indexOf('@');
    return at > -1 ? s.substring(0, at).toLowerCase() : '';
  }
  function isGeneric(e) {
    var lp = localPart(e);
    if (!lp) { return true; }
    for (var i = 0; i < GENERIC.length; i++) { if (lp === GENERIC[i]) { return true; } }
    return false;
  }
  function domainOf(w) {
    var d = String(w || '').toLowerCase();
    if (d.indexOf('://') !== -1) { d = d.split('://')[1]; }
    if (d.indexOf('www.') === 0) { d = d.substring(4); }
    return d.split('/')[0].split('?')[0].trim();
  }

  var items = $input.all();
  var out = [];
  var n = 0;

  if (enabled) {
    for (var i = 0; i < items.length; i++) {
      var lead = items[i].json;
      if (!lead || lead._error) { continue; }
      var email = lead.email || '';
      var isP1 = (lead.priority === '1');

      var wantCall = false;
      if (!email && lead.website) { wantCall = true; }
      else if (isP1 && email && isGeneric(email) && lead.website) { wantCall = true; }
      if (!wantCall) { continue; }

      if (maxCalls > 0 && n >= maxCalls) { break; }
      n++;
      out.push({ json: { _needEnrich: true, _key: lead._key || '', _domain: domainOf(lead.website) } });
    }
  }

  if (!out.length) { return [{ json: { _needEnrich: false, _queued: 0 } }]; }
  return out;
} catch (e) {
  return [{ json: { _needEnrich: false, _queued: 0, _prepError: e.message } }];
}

// Stage 8 (merge) - fold Instantly results back, then derive a first name from
// a personal email local-part wherever Instantly did not supply one, so the
// greeting fallback fires less often.
try {
  var leadItems = $('🔗 Merge Claude').all();
  var leads = [];
  for (var i = 0; i < leadItems.length; i++) {
    if (leadItems[i].json) { leads.push(leadItems[i].json); }
  }
  if (!leads.length) { return [{ json: { _error: 'Merge Enrich got 0 leads' } }]; }

  var ownerTitles = ['owner','director','founder','manager','ceo','md','managing director','partner'];
  var GENERIC = ['info','sales','enquiries','enquiry','admin','contact','hello',
                 'office','accounts','mail','support','team','service','post','general'];
  function localPart(e) {
    var s = String(e || '');
    var at = s.indexOf('@');
    return at > -1 ? s.substring(0, at).toLowerCase() : '';
  }
  function isGeneric(e) {
    var lp = localPart(e);
    if (!lp) { return true; }
    for (var g = 0; g < GENERIC.length; g++) { if (lp === GENERIC[g]) { return true; } }
    return false;
  }
  function nameFromEmail(e) {
    var lp = localPart(e);
    if (!lp || isGeneric(e)) { return ''; }
    var first = lp.split(/[._-]/)[0];
    if (!first || first.length < 2 || first.length > 14) { return ''; }
    if (!/^[a-z]+$/.test(first)) { return ''; }
    return first.charAt(0).toUpperCase() + first.substring(1);
  }

  var stats = { called: 0, ok: 0, failed: 0, nameFromEmail: 0 };

  // Pair responses to queued leads by position - the HTTP node emits exactly one
  // output item per input item, in order.
  var byKey = {};
  try {
    var prep = $('🔍 Prep Enrich').all();
    var resp = $('🔍 Instantly Search').all();
    for (var p = 0; p < prep.length && p < resp.length; p++) {
      var pk = prep[p].json._key;
      if (!pk || prep[p].json._needEnrich !== true) { continue; }
      stats.called++;
      var response = resp[p].json;
      if (!response || response.error) { stats.failed++; continue; }

      var people = [];
      if (Array.isArray(response.data)) { people = response.data; }
      else if (Array.isArray(response.results)) { people = response.results; }
      else if (Array.isArray(response)) { people = response; }
      if (!people.length) { continue; }

      var best = null;
      for (var j = 0; j < people.length && !best; j++) {
        var title = String(people[j].title || people[j].job_title || '').toLowerCase();
        for (var t = 0; t < ownerTitles.length; t++) {
          if (title.indexOf(ownerTitles[t]) !== -1) { best = people[j]; break; }
        }
      }
      if (!best) { best = people[0]; }
      byKey[pk] = best;
      stats.ok++;
    }
  } catch (eR) { }

  var out = [];
  for (var k = 0; k < leads.length; k++) {
    var lead = leads[k];
    var firstName = lead.firstName || '';
    var email = lead.email || '';
    var linkedinUrl = lead.linkedinUrl || '';

    var hit = byKey[lead._key];
    if (hit) {
      var fn = hit.first_name || hit.firstName || '';
      if (fn) { firstName = fn; }
      var fe = hit.email || '';
      if (fe && (!email || isGeneric(email))) { email = fe; lead.emailSource = 'instantly'; }
      if (!linkedinUrl) { linkedinUrl = hit.linkedin_url || hit.linkedinUrl || hit.linkedin || ''; }
    }

    if (!firstName && email) {
      var derived = nameFromEmail(email);
      if (derived) { firstName = derived; stats.nameFromEmail++; }
    }

    lead.firstName = firstName;
    lead.email = email;
    lead.linkedinUrl = linkedinUrl;
    if (!lead.emailSource && email) { lead.emailSource = 'mcs'; }
    out.push({ json: lead });
  }

  out[0].json._enrichStats = stats;
  return out;
} catch (e) {
  var fallback = [];
  try {
    var itms = $('🔗 Merge Claude').all();
    for (var f = 0; f < itms.length; f++) { fallback.push({ json: itms[f].json }); }
  } catch (e3) { }
  if (fallback.length) { fallback[0].json._enrichStats = { error: e.message }; }
  return fallback.length ? fallback : [{ json: { _error: 'Merge Enrich failed: ' + e.message } }];
}
